REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (10,10,2569,0,'{\"text\": \"โรงเรียนจัดการศึกษาแบบสหศึกษาในระดับมัธยมศึกษาปีที่ 1 ถึงมัธยมศึกษาปีที่ 6 มีทั้งหลักสูตรมัธยมศึกษาตอนต้น แผนการเรียนมัธยมศึกษาตอนปลาย และห้องเรียนพิเศษที่ตอบสนองศักยภาพและความสนใจของผู้เรียน การบริหารจัดการใช้การมีส่วนร่วมของผู้บริหาร ครู บุคลากร ผู้ปกครอง ชุมชนและภาคีเครือข่าย และขับเคลื่อนงานด้วย BANCHUEN Model ร่วมกับวงจรคุณภาพ PDCA\"}',NULL,'2026-10-30 09:51:38');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (11,11,2569,0,'{\"text\": \"โรงเรียนสันทรายวิทยาคมก่อตั้งเมื่อวันที่ 14 มิถุนายน พ.ศ. 2516 ตามประกาศกรมสามัญศึกษา โดยได้รับอนุญาตให้ใช้พื้นที่ของสหกรณ์เป็นสถานที่ตั้งโรงเรียน เปิดสอนครั้งแรกในระดับชั้นมัธยมศึกษาปีที่ 1 จำนวน 2 ห้องเรียน มีนักเรียน 99 คน ในระยะแรกยังไม่มีอาคารเรียนถาวร ชุมชนได้ร่วมบริจาควัสดุและแรงงานสร้างอาคารเรียนชั่วคราวขนาด 2 ห้องเรียน และเปิดใช้เมื่อวันที่ 17 มิถุนายน พ.ศ. 2516 ต่อมาโรงเรียนพัฒนาการจัดการศึกษาและระบบประกันคุณภาพอย่างต่อเนื่อง ได้รับรางวัลและการยอมรับหลายรายการ รวมทั้งเป็นโรงเรียนมาตรฐานสากลระดับ SCQA ผ่านเกณฑ์ OBECQA และได้รับรางวัล IQA AWARD\"}',NULL,'2026-10-30 09:51:37');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (12,12,2569,0,'{\"text\": \"โรงเรียนสันทรายวิทยาคม ตั้งอยู่เลขที่ 207 หมู่ที่ 10 ถนนเชียงใหม่-พร้าว ตำบลหนองหาร อำเภอสันทราย จังหวัดเชียงใหม่ รหัสไปรษณีย์ 50291 โทรศัพท์ 053-353872 และ 086-4294794 อีเมล sansaiwit@gmail.com เว็บไซต์ http://www.sansai.ac.th สังกัดสำนักงานเขตพื้นที่การศึกษามัธยมศึกษาเชียงใหม่ สำนักงานคณะกรรมการการศึกษาขั้นพื้นฐาน กระทรวงศึกษาธิการ เปิดสอนระดับชั้นมัธยมศึกษาปีที่ 1 ถึงมัธยมศึกษาปีที่ 6\"}',NULL,'2026-10-30 09:51:37');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (13,13,2569,0,'{\"rows\": [{\"c1\": \"ตราสัญลักษณ์ประจำโรงเรียน\", \"c2\": \"ประกอบด้วยพญานาคคู่ หมายถึงน้ำ ความอุดมสมบูรณ์และครูผู้ให้ชีวิต ความรู้และความรักแก่ศิษย์ และดอกบานชื่น หมายถึงนักเรียนผู้เบิกบานสดชื่น พร้อมนำความรู้ไปใช้ให้เกิดประโยชน์\"}, {\"c1\": \"อักษรย่อ\", \"c2\": \"ส.ค.\"}, {\"c1\": \"สีประจำโรงเรียน\", \"c2\": \"น้ำเงิน-ขาว สีน้ำเงินหมายถึงความเข้มแข็ง ความอดทนและความหนักแน่น สีขาวหมายถึงความบริสุทธิ์ แสงสว่างและแสงแห่งปัญญา\"}, {\"c1\": \"ธงประจำโรงเรียน\", \"c2\": \"\"}, {\"c1\": \"ดอกไม้ประจำโรงเรียน\", \"c2\": \"เอกสารระบุดอกบานชื่นเป็นส่วนหนึ่งของตราสัญลักษณ์ แต่ยังไม่พบการยืนยันว่าเป็นดอกไม้ประจำโรงเรียนอย่างเป็นทางการ\"}, {\"c1\": \"อัตลักษณ์ของลูกสันทราย\", \"c2\": \"ยิ้ม ไหว้ ทักทาย สุภาพอ่อนน้อม แต่งกายดี มีจิตสาธารณะ\"}]}',NULL,'2026-10-30 09:51:37');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (14,14,2569,0,'{\"text\": \"โรงเรียนสันทรายวิทยาคมเป็นโรงเรียนสหศึกษา เปิดสอนระดับมัธยมศึกษาปีที่ 1 ถึงมัธยมศึกษาปีที่ 6 สังกัดสำนักงานเขตพื้นที่การศึกษามัธยมศึกษาเชียงใหม่ สำนักงานคณะกรรมการการศึกษาขั้นพื้นฐาน กระทรวงศึกษาธิการ เป็นสถานศึกษาระดับมัธยมศึกษาขนาดใหญ่ โรงเรียนมาตรฐานสากล และโรงเรียนนำร่องในพื้นที่นวัตกรรมการศึกษาจังหวัดเชียงใหม่\"}',NULL,'2026-10-30 09:51:38');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (15,15,2569,0,'{\"text\": \"ชุมชนรอบโรงเรียนมีลักษณะกึ่งเมืองกึ่งชนบท เป็นชุมชนของชนพื้นราบ ประชากรอำเภอสันทรายตามข้อมูลปี 2567 ประมาณ 145,595 คน มีเด็กในวัยเรียนประมาณ 26,028 คน อาชีพสำคัญคือเกษตรกรรมและรับจ้าง ประชาชนส่วนใหญ่นับถือศาสนาพุทธ โรงเรียนได้รับความร่วมมือจากมหาวิทยาลัยแม่โจ้ ชุมชน ผู้ปกครอง และหน่วยงานราชการในท้องถิ่นในการพัฒนาการศึกษา การคมนาคมสะดวกและมีสาธารณูปโภคสนับสนุนการดำเนินชีวิต\"}',NULL,'2026-10-30 09:51:37');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (16,16,2569,0,'{\"text\": \"วิสัยทัศน์: [ตัวอย่าง] ข้อความวิสัยทัศน์ของโรงเรียน\\nพันธกิจ: [ตัวอย่าง] 1) พัฒนาคุณภาพผู้เรียน 2) พัฒนาครูและบุคลากร 3) พัฒนาระบบบริหารจัดการ 4) ส่งเสริมความร่วมมือกับชุมชน\\nเป้าประสงค์: [ตัวอย่าง] ผู้เรียนมีคุณภาพตามมาตรฐาน ครูมีสมรรถนะในการจัดการเรียนรู้ โรงเรียนมีระบบบริหารที่มีประสิทธิภาพ\"}',NULL,'2026-10-02 09:33:53');
