REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (276,11,2566,0,'{\"text\":\"โรงเรียนสันทรายวิทยาคมเป็นโรงเรียนสหศึกษา สังกัดสำนักงานเขตพื้นที่การศึกษามัธยมศึกษาเชียงใหม่ ก่อตั้งเมื่อวันที่ 14 มิถุนายน พ.ศ. 2516 และเปิดสอนครั้งแรกในระดับชั้นมัธยมศึกษาปีที่ 1 จำนวน 2 ห้องเรียน นักเรียน 99 คน บนพื้นที่ 35 ไร่ 2 งาน 5 ตารางวา การก่อตั้งเกิดจากความร่วมมือของหน่วยงานรัฐและชุมชนตำบลหนองหาร ซึ่งร่วมบริจาควัสดุและแรงงานสร้างอาคารเรียนชั่วคราวหลังแรก\\n\\nในระยะแรกโรงเรียนอาศัยอาคารเรียนชั่วคราวที่ชุมชนร่วมกันจัดสร้าง ก่อนพัฒนาอาคาร สถานที่ และระบบการจัดการศึกษาให้รองรับผู้เรียนระดับมัธยมศึกษาในพื้นที่อำเภอสันทราย การเติบโตของโรงเรียนจึงสะท้อนความร่วมมือระหว่างสถานศึกษา หน่วยงานภาครัฐ ผู้นำชุมชน ผู้ปกครอง และประชาชนในท้องถิ่นมาอย่างต่อเนื่อง\"}',NULL,'2026-10-06 08:40:55');
