REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (279,12,2566,0,'{\"text\":\"โรงเรียนตั้งอยู่เลขที่ 207 หมู่ 10 ถนนเชียงใหม่-พร้าว ตำบลหนองหาร อำเภอสันทราย จังหวัดเชียงใหม่ รหัสไปรษณีย์ 50290 เปิดสอนระดับมัธยมศึกษาตอนต้นถึงมัธยมศึกษาตอนปลาย และจัดการศึกษาโดยยึดการมีส่วนร่วมของผู้บริหาร ครู บุคลากร นักเรียน ผู้ปกครอง คณะกรรมการสถานศึกษา และชุมชน\\n\\nการบริหารแบ่งภารกิจเป็น 4 กลุ่ม ได้แก่ บริหารวิชาการ บริหารงบประมาณ บริหารงานบุคคล และบริหารทั่วไป แต่ละกลุ่มเชื่อมโยงแผนงาน ตัวชี้วัด โครงการ และข้อมูลสารสนเทศเข้ากับเป้าหมายคุณภาพผู้เรียน มีการกำกับติดตามและรายงานผลตามรอบปีการศึกษา\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (280,12,2567,0,'{\"text\":\"โรงเรียนตั้งอยู่เลขที่ 207 หมู่ 10 ถนนเชียงใหม่-พร้าว ตำบลหนองหาร อำเภอสันทราย จังหวัดเชียงใหม่ รหัสไปรษณีย์ 50290 เปิดสอนระดับมัธยมศึกษาตอนต้นถึงมัธยมศึกษาตอนปลาย และจัดการศึกษาโดยยึดการมีส่วนร่วมของผู้บริหาร ครู บุคลากร นักเรียน ผู้ปกครอง คณะกรรมการสถานศึกษา และชุมชน\\n\\nการบริหารแบ่งภารกิจเป็น 4 กลุ่ม ได้แก่ บริหารวิชาการ บริหารงบประมาณ บริหารงานบุคคล และบริหารทั่วไป แต่ละกลุ่มเชื่อมโยงแผนงาน ตัวชี้วัด โครงการ และข้อมูลสารสนเทศเข้ากับเป้าหมายคุณภาพผู้เรียน มีการกำกับติดตามและรายงานผลตามรอบปีการศึกษา\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (281,12,2568,0,'{\"text\":\"โรงเรียนตั้งอยู่เลขที่ 207 หมู่ 10 ถนนเชียงใหม่-พร้าว ตำบลหนองหาร อำเภอสันทราย จังหวัดเชียงใหม่ รหัสไปรษณีย์ 50290 เปิดสอนระดับมัธยมศึกษาตอนต้นถึงมัธยมศึกษาตอนปลาย และจัดการศึกษาโดยยึดการมีส่วนร่วมของผู้บริหาร ครู บุคลากร นักเรียน ผู้ปกครอง คณะกรรมการสถานศึกษา และชุมชน\\n\\nการบริหารแบ่งภารกิจเป็น 4 กลุ่ม ได้แก่ บริหารวิชาการ บริหารงบประมาณ บริหารงานบุคคล และบริหารทั่วไป แต่ละกลุ่มเชื่อมโยงแผนงาน ตัวชี้วัด โครงการ และข้อมูลสารสนเทศเข้ากับเป้าหมายคุณภาพผู้เรียน มีการกำกับติดตามและรายงานผลตามรอบปีการศึกษา\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (282,15,2566,0,'{\"text\":\"โรงเรียนเชื่อมโยงการจัดการศึกษากับบริบทอำเภอสันทรายและภูมิปัญญาท้องถิ่น โดยเปิดโอกาสให้ชุมชน หน่วยงานภายนอก สถานประกอบการ และสถาบันอุดมศึกษามีส่วนร่วมเป็นแหล่งเรียนรู้ เครือข่ายวิชาการ และผู้สนับสนุนกิจกรรมของผู้เรียน\\n\\nเครือข่ายถูกนำมาใช้ทั้งด้านวิทยากร แหล่งฝึกประสบการณ์ ห้องปฏิบัติการ การแนะแนวศึกษาต่อ และการพัฒนาทักษะอาชีพ ตัวอย่างหน่วยงานที่ร่วมสนับสนุน ได้แก่ มหาวิทยาลัยแม่โจ้ มหาวิทยาลัยเชียงใหม่ โรงพยาบาล สถานประกอบการ และองค์กรปกครองส่วนท้องถิ่น ทำให้ผู้เรียนได้เรียนรู้จากสถานการณ์และผู้เชี่ยวชาญจริง\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (283,15,2567,0,'{\"text\":\"โรงเรียนเชื่อมโยงการจัดการศึกษากับบริบทอำเภอสันทรายและภูมิปัญญาท้องถิ่น โดยเปิดโอกาสให้ชุมชน หน่วยงานภายนอก สถานประกอบการ และสถาบันอุดมศึกษามีส่วนร่วมเป็นแหล่งเรียนรู้ เครือข่ายวิชาการ และผู้สนับสนุนกิจกรรมของผู้เรียน\\n\\nเครือข่ายถูกนำมาใช้ทั้งด้านวิทยากร แหล่งฝึกประสบการณ์ ห้องปฏิบัติการ การแนะแนวศึกษาต่อ และการพัฒนาทักษะอาชีพ ตัวอย่างหน่วยงานที่ร่วมสนับสนุน ได้แก่ มหาวิทยาลัยแม่โจ้ มหาวิทยาลัยเชียงใหม่ โรงพยาบาล สถานประกอบการ และองค์กรปกครองส่วนท้องถิ่น ทำให้ผู้เรียนได้เรียนรู้จากสถานการณ์และผู้เชี่ยวชาญจริง\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (284,15,2568,0,'{\"text\":\"โรงเรียนเชื่อมโยงการจัดการศึกษากับบริบทอำเภอสันทรายและภูมิปัญญาท้องถิ่น โดยเปิดโอกาสให้ชุมชน หน่วยงานภายนอก สถานประกอบการ และสถาบันอุดมศึกษามีส่วนร่วมเป็นแหล่งเรียนรู้ เครือข่ายวิชาการ และผู้สนับสนุนกิจกรรมของผู้เรียน\\n\\nเครือข่ายถูกนำมาใช้ทั้งด้านวิทยากร แหล่งฝึกประสบการณ์ ห้องปฏิบัติการ การแนะแนวศึกษาต่อ และการพัฒนาทักษะอาชีพ ตัวอย่างหน่วยงานที่ร่วมสนับสนุน ได้แก่ มหาวิทยาลัยแม่โจ้ มหาวิทยาลัยเชียงใหม่ โรงพยาบาล สถานประกอบการ และองค์กรปกครองส่วนท้องถิ่น ทำให้ผู้เรียนได้เรียนรู้จากสถานการณ์และผู้เชี่ยวชาญจริง\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (285,16,2566,0,'{\"text\":\"วิสัยทัศน์: โรงเรียนสันทรายวิทยาคมเป็นสถานศึกษาที่สร้างสรรค์คนดี มีทักษะแห่งอนาคต มุ่งสู่ความเป็นเลิศตามศักยภาพ ภายในปี 2570\\nพันธกิจสำคัญ ได้แก่ พัฒนาผู้เรียนให้มีทักษะแห่งอนาคตและความเป็นเลิศ ส่งเสริมคุณลักษณะที่พึงประสงค์และภูมิคุ้มกันจากภัย เพิ่มโอกาสทางการศึกษาอย่างเท่าเทียม พัฒนาครูตามมาตรฐานวิชาชีพ และพัฒนาระบบบริหารจัดการให้สอดคล้องกับบริบท\\n\\nเป้าประสงค์ครอบคลุมการพัฒนาทักษะแห่งอนาคต การส่งเสริมความเป็นเลิศตามศักยภาพ การปลูกฝังค่านิยมที่ดีบนพื้นฐานความเป็นไทย การสร้างภูมิคุ้มกันจากภัยทุกรูปแบบ และการจัดโอกาสทางการศึกษาอย่างเท่าเทียม นอกจากนี้ยังมุ่งให้ครูเชี่ยวชาญตามมาตรฐานวิชาชีพ และให้ระบบบริหาร สภาพแวดล้อม เทคโนโลยี และการประกันคุณภาพสนับสนุนการเรียนรู้ได้จริง\"}',NULL,'2026-10-06 08:40:55');
