REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (288,17,2566,0,'{\"text\":\"ปรัชญา: วิชาเป็นเลิศ เทิดคุณธรรม นำสามัคคี\\nวัฒนธรรมองค์กร: ผู้บริหาร ครู บุคลากร และนักเรียนรักสามัคคี ศรัทธาและภูมิใจในสถาบันตามวิถีสันทราย\\nวิถีสันทราย: ยิ้มไหว้ทักทาย สุภาพอ่อนน้อม แต่งกายดี มีจิตสาธารณะ\\nค่านิยม: องค์กรแห่งอนาคต\\n\\nแนวคิดดังกล่าวถูกนำไปใช้ในกิจกรรมหน้าเสาธง การดูแลช่วยเหลือนักเรียน กิจกรรมสภานักเรียน งานบริการชุมชน และการจัดการเรียนรู้ เพื่อให้พฤติกรรมยิ้ม ไหว้ ทักทาย ความสุภาพ การแต่งกายเหมาะสม และจิตสาธารณะปรากฏเป็นวิถีปฏิบัติประจำวัน ไม่ใช่เพียงข้อความประชาสัมพันธ์ของโรงเรียน\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (289,17,2567,0,'{\"text\":\"ปรัชญา: วิชาเป็นเลิศ เทิดคุณธรรม นำสามัคคี\\nวัฒนธรรมองค์กร: ผู้บริหาร ครู บุคลากร และนักเรียนรักสามัคคี ศรัทธาและภูมิใจในสถาบันตามวิถีสันทราย\\nวิถีสันทราย: ยิ้มไหว้ทักทาย สุภาพอ่อนน้อม แต่งกายดี มีจิตสาธารณะ\\nค่านิยม: องค์กรแห่งอนาคต\\n\\nแนวคิดดังกล่าวถูกนำไปใช้ในกิจกรรมหน้าเสาธง การดูแลช่วยเหลือนักเรียน กิจกรรมสภานักเรียน งานบริการชุมชน และการจัดการเรียนรู้ เพื่อให้พฤติกรรมยิ้ม ไหว้ ทักทาย ความสุภาพ การแต่งกายเหมาะสม และจิตสาธารณะปรากฏเป็นวิถีปฏิบัติประจำวัน ไม่ใช่เพียงข้อความประชาสัมพันธ์ของโรงเรียน\"}',NULL,'2026-10-06 08:40:55');
