REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (291,18,2566,0,'{\"text\":\"กลยุทธ์ปีการศึกษา 2568-2570 มุ่ง 3 ด้าน ได้แก่ 1) พัฒนาผู้เรียนให้มีทักษะแห่งอนาคตและเป็นเลิศตามศักยภาพ 2) พัฒนาครูและบุคลากรให้จัดการศึกษาที่สนับสนุนทักษะแห่งอนาคต และ 3) พัฒนาระบบบริหารจัดการให้มีประสิทธิภาพผ่านการมีส่วนร่วม เทคโนโลยีดิจิทัล สภาพแวดล้อมที่ปลอดภัย การใช้งบประมาณอย่างคุ้มค่า และระบบประกันคุณภาพ\\n\\nแต่ละกลยุทธ์ถูกแปลงเป็นแผนปฏิบัติการ โครงการ ผู้รับผิดชอบ งบประมาณ และตัวชี้วัดที่ตรวจสอบได้ เช่น การพัฒนาการเรียนรู้เชิงรุก การใช้เทคโนโลยีดิจิทัล การดูแลความปลอดภัย การสร้างเครือข่าย และการบริหารงบประมาณอย่างโปร่งใส ผลการดำเนินงานถูกติดตามเพื่อนำกลับไปปรับแผนในรอบต่อไป\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (292,18,2567,0,'{\"text\":\"กลยุทธ์ปีการศึกษา 2568-2570 มุ่ง 3 ด้าน ได้แก่ 1) พัฒนาผู้เรียนให้มีทักษะแห่งอนาคตและเป็นเลิศตามศักยภาพ 2) พัฒนาครูและบุคลากรให้จัดการศึกษาที่สนับสนุนทักษะแห่งอนาคต และ 3) พัฒนาระบบบริหารจัดการให้มีประสิทธิภาพผ่านการมีส่วนร่วม เทคโนโลยีดิจิทัล สภาพแวดล้อมที่ปลอดภัย การใช้งบประมาณอย่างคุ้มค่า และระบบประกันคุณภาพ\\n\\nแต่ละกลยุทธ์ถูกแปลงเป็นแผนปฏิบัติการ โครงการ ผู้รับผิดชอบ งบประมาณ และตัวชี้วัดที่ตรวจสอบได้ เช่น การพัฒนาการเรียนรู้เชิงรุก การใช้เทคโนโลยีดิจิทัล การดูแลความปลอดภัย การสร้างเครือข่าย และการบริหารงบประมาณอย่างโปร่งใส ผลการดำเนินงานถูกติดตามเพื่อนำกลับไปปรับแผนในรอบต่อไป\"}',NULL,'2026-10-06 08:40:55');
