REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (294,136,2566,0,'{\"text\":\"โรงเรียนใช้ BANCHUEN Model ร่วมกับวงจรคุณภาพ PDCA เป็นกรอบบริหารงานทั้ง 4 กลุ่มบริหาร เริ่มจากการระดมความคิดเห็นและวิเคราะห์ข้อมูล กำหนดแผนและผู้รับผิดชอบ ดำเนินงานโดยใช้เครือข่ายและเทคโนโลยี กำกับติดตามผล และนำผลประเมินกลับมาปรับปรุงงานอย่างต่อเนื่อง โดยเปิดโอกาสให้ครู นักเรียน ผู้ปกครอง คณะกรรมการสถานศึกษา ชุมชน และหน่วยงานภายนอกมีส่วนร่วม\\n\\nกระบวนการเริ่มจาก Brainstorming เพื่อวิเคราะห์ปัญหาและความต้องการ แล้วกำหนดกิจกรรม เครือข่าย ทรัพยากร และเป้าหมายร่วมกัน จากนั้นดำเนินงานผ่านโครงการของทั้ง 4 กลุ่มบริหาร ตรวจสอบด้วยข้อมูลและผลประเมิน และสรุปบทเรียนเพื่อพัฒนารอบใหม่ รูปแบบเดียวกันนี้ถูกนำไปใช้กับงานสวนพฤกษศาสตร์ กลุ่มแผนการเรียน และระบบประกันคุณภาพของโรงเรียน\"}',NULL,'2026-10-06 08:40:55');
