REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (297,137,2566,0,'{\"text\":\"โรงเรียนดำเนินระบบประกันคุณภาพภายในอย่างต่อเนื่องตามกฎกระทรวงการประกันคุณภาพการศึกษา พ.ศ. 2561 ใช้ข้อมูลสารสนเทศและผลการประเมินเป็นฐานในการกำหนดเป้าหมาย แผนพัฒนาคุณภาพ และแผนปฏิบัติการประจำปี มีการติดตาม ตรวจสอบ สรุปผล และรายงานต่อผู้เกี่ยวข้อง พร้อมพัฒนาระบบตามแนวทาง SCQA และ OBECQA\\n\\nโรงเรียนกำหนดให้การประกันคุณภาพเป็นส่วนหนึ่งของงานประจำ มิใช่การจัดเอกสารเฉพาะช่วงรับการประเมิน โดยเชื่อมมาตรฐานสถานศึกษาเข้ากับแผนพัฒนาการจัดการศึกษา พ.ศ. 2568-2570 แผนปฏิบัติการ และรายงานผล มีการทบทวนหลักฐานเชิงประจักษ์ร่วมกัน และสร้างความเข้าใจว่าผู้บริหาร ครู บุคลากร นักเรียน ผู้ปกครอง คณะกรรมการสถานศึกษา และภาคีเครือข่ายมีส่วนรับผิดชอบต่อวัฒนธรรมคุณภาพร่วมกัน\"}',NULL,'2026-10-06 08:40:55');
