REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (300,138,2566,0,'{\"text\":\"ผู้บริหารกำหนดทิศทางและมอบหมายงานตามโครงสร้างบริหารอย่างชัดเจน สนับสนุนการทำงานเป็นทีม การแลกเปลี่ยนเรียนรู้ และการใช้ข้อมูลประกอบการตัดสินใจ รวมทั้งประสานเครือข่ายกับสถาบันอุดมศึกษา หน่วยงานท้องถิ่น ชุมชน และสถานประกอบการเพื่อยกระดับโอกาสและคุณภาพของผู้เรียน\\n\\nผู้บริหารใช้การประชุม การนิเทศ และข้อมูลผลลัพธ์ของผู้เรียนติดตามงาน พร้อมเปิดพื้นที่ให้หัวหน้ากลุ่มงานและครูร่วมเสนอแนวทางแก้ปัญหา เครือข่ายภายนอกเข้ามาสนับสนุนทั้งความรู้เฉพาะด้าน สถานที่ฝึกปฏิบัติ การศึกษาดูงาน และเวทีเผยแพร่ผลงาน ทำให้การบริหารไม่จำกัดอยู่เฉพาะทรัพยากรภายในโรงเรียน\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (301,138,2567,0,'{\"text\":\"ผู้บริหารกำหนดทิศทางและมอบหมายงานตามโครงสร้างบริหารอย่างชัดเจน สนับสนุนการทำงานเป็นทีม การแลกเปลี่ยนเรียนรู้ และการใช้ข้อมูลประกอบการตัดสินใจ รวมทั้งประสานเครือข่ายกับสถาบันอุดมศึกษา หน่วยงานท้องถิ่น ชุมชน และสถานประกอบการเพื่อยกระดับโอกาสและคุณภาพของผู้เรียน\\n\\nผู้บริหารใช้การประชุม การนิเทศ และข้อมูลผลลัพธ์ของผู้เรียนติดตามงาน พร้อมเปิดพื้นที่ให้หัวหน้ากลุ่มงานและครูร่วมเสนอแนวทางแก้ปัญหา เครือข่ายภายนอกเข้ามาสนับสนุนทั้งความรู้เฉพาะด้าน สถานที่ฝึกปฏิบัติ การศึกษาดูงาน และเวทีเผยแพร่ผลงาน ทำให้การบริหารไม่จำกัดอยู่เฉพาะทรัพยากรภายในโรงเรียน\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (302,138,2568,0,'{\"text\":\"ผู้บริหารกำหนดทิศทางและมอบหมายงานตามโครงสร้างบริหารอย่างชัดเจน สนับสนุนการทำงานเป็นทีม การแลกเปลี่ยนเรียนรู้ และการใช้ข้อมูลประกอบการตัดสินใจ รวมทั้งประสานเครือข่ายกับสถาบันอุดมศึกษา หน่วยงานท้องถิ่น ชุมชน และสถานประกอบการเพื่อยกระดับโอกาสและคุณภาพของผู้เรียน\\n\\nผู้บริหารใช้การประชุม การนิเทศ และข้อมูลผลลัพธ์ของผู้เรียนติดตามงาน พร้อมเปิดพื้นที่ให้หัวหน้ากลุ่มงานและครูร่วมเสนอแนวทางแก้ปัญหา เครือข่ายภายนอกเข้ามาสนับสนุนทั้งความรู้เฉพาะด้าน สถานที่ฝึกปฏิบัติ การศึกษาดูงาน และเวทีเผยแพร่ผลงาน ทำให้การบริหารไม่จำกัดอยู่เฉพาะทรัพยากรภายในโรงเรียน\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (303,139,2566,0,'{\"text\":\"โรงเรียนส่งเสริมให้ครูและบุคลากรพัฒนาความรู้และทักษะด้านการจัดการเรียนรู้เชิงรุก การวัดและประเมินผล การใช้สื่อและเทคโนโลยี การวิจัยและนวัตกรรมในชั้นเรียน ตลอดจนการแลกเปลี่ยนเรียนรู้ผ่านชุมชนการเรียนรู้ทางวิชาชีพ เพื่อนำผลการพัฒนาไปใช้ปรับปรุงการเรียนรู้ของผู้เรียน\\n\\nการพัฒนาครูเชื่อมกับกลยุทธ์การสร้างทักษะแห่งอนาคต โดยเน้นให้ครูออกแบบ Active Learning ใช้เทคโนโลยีดิจิทัล วัดผลด้วยวิธีที่หลากหลาย และผลิตสื่อหรือนวัตกรรมที่ใช้ได้จริงในชั้นเรียน โรงเรียนใช้การอบรม การนิเทศ การศึกษาดูงาน และ PLC เพื่อให้ครูร่วมวิเคราะห์ปัญหาผู้เรียน ทดลองแนวทาง สะท้อนผล และเผยแพร่แนวปฏิบัติที่ดี\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (304,139,2567,0,'{\"text\":\"โรงเรียนส่งเสริมให้ครูและบุคลากรพัฒนาความรู้และทักษะด้านการจัดการเรียนรู้เชิงรุก การวัดและประเมินผล การใช้สื่อและเทคโนโลยี การวิจัยและนวัตกรรมในชั้นเรียน ตลอดจนการแลกเปลี่ยนเรียนรู้ผ่านชุมชนการเรียนรู้ทางวิชาชีพ เพื่อนำผลการพัฒนาไปใช้ปรับปรุงการเรียนรู้ของผู้เรียน\\n\\nการพัฒนาครูเชื่อมกับกลยุทธ์การสร้างทักษะแห่งอนาคต โดยเน้นให้ครูออกแบบ Active Learning ใช้เทคโนโลยีดิจิทัล วัดผลด้วยวิธีที่หลากหลาย และผลิตสื่อหรือนวัตกรรมที่ใช้ได้จริงในชั้นเรียน โรงเรียนใช้การอบรม การนิเทศ การศึกษาดูงาน และ PLC เพื่อให้ครูร่วมวิเคราะห์ปัญหาผู้เรียน ทดลองแนวทาง สะท้อนผล และเผยแพร่แนวปฏิบัติที่ดี\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (305,139,2568,0,'{\"text\":\"โรงเรียนส่งเสริมให้ครูและบุคลากรพัฒนาความรู้และทักษะด้านการจัดการเรียนรู้เชิงรุก การวัดและประเมินผล การใช้สื่อและเทคโนโลยี การวิจัยและนวัตกรรมในชั้นเรียน ตลอดจนการแลกเปลี่ยนเรียนรู้ผ่านชุมชนการเรียนรู้ทางวิชาชีพ เพื่อนำผลการพัฒนาไปใช้ปรับปรุงการเรียนรู้ของผู้เรียน\\n\\nการพัฒนาครูเชื่อมกับกลยุทธ์การสร้างทักษะแห่งอนาคต โดยเน้นให้ครูออกแบบ Active Learning ใช้เทคโนโลยีดิจิทัล วัดผลด้วยวิธีที่หลากหลาย และผลิตสื่อหรือนวัตกรรมที่ใช้ได้จริงในชั้นเรียน โรงเรียนใช้การอบรม การนิเทศ การศึกษาดูงาน และ PLC เพื่อให้ครูร่วมวิเคราะห์ปัญหาผู้เรียน ทดลองแนวทาง สะท้อนผล และเผยแพร่แนวปฏิบัติที่ดี\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (306,140,2566,0,'{\"text\":\"โรงเรียนวิเคราะห์ความต้องการจำเป็นของผู้เรียน ชุมชน สังคม ท้องถิ่น และผู้มีส่วนเกี่ยวข้อง แล้วนำผลมาพัฒนาหลักสูตรให้ยืดหยุ่นและสอดคล้องกับหลักสูตรแกนกลาง ออกแบบการจัดการเรียนการสอนตามจุดมุ่งหมาย จัดทำแผนนิเทศ กำกับ ติดตาม และประเมินการใช้หลักสูตร ก่อนนำผลมาปรับปรุงหลักสูตรอย่างต่อเนื่อง\\n\\nคณะทำงานศึกษาหลักสูตรแกนกลาง มาตรฐานและตัวชี้วัด วิเคราะห์ข้อมูลผู้เรียนเป็นรายบุคคล รวมทั้งรับฟังความคิดเห็นจากผู้ปกครอง ชุมชน และหน่วยงานที่เกี่ยวข้อง ก่อนกำหนดโครงสร้างรายวิชาและแผนการเรียน โรงเรียนติดตามทั้งผลสัมฤทธิ์ สมรรถนะ คุณลักษณะ และความพร้อมศึกษาต่อ แล้วใช้ผลนิเทศและประเมินหลักสูตรปรับเนื้อหา เวลาเรียน และกิจกรรมให้เหมาะกับผู้เรียนแต่ละกลุ่ม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (307,140,2567,0,'{\"text\":\"โรงเรียนวิเคราะห์ความต้องการจำเป็นของผู้เรียน ชุมชน สังคม ท้องถิ่น และผู้มีส่วนเกี่ยวข้อง แล้วนำผลมาพัฒนาหลักสูตรให้ยืดหยุ่นและสอดคล้องกับหลักสูตรแกนกลาง ออกแบบการจัดการเรียนการสอนตามจุดมุ่งหมาย จัดทำแผนนิเทศ กำกับ ติดตาม และประเมินการใช้หลักสูตร ก่อนนำผลมาปรับปรุงหลักสูตรอย่างต่อเนื่อง\\n\\nคณะทำงานศึกษาหลักสูตรแกนกลาง มาตรฐานและตัวชี้วัด วิเคราะห์ข้อมูลผู้เรียนเป็นรายบุคคล รวมทั้งรับฟังความคิดเห็นจากผู้ปกครอง ชุมชน และหน่วยงานที่เกี่ยวข้อง ก่อนกำหนดโครงสร้างรายวิชาและแผนการเรียน โรงเรียนติดตามทั้งผลสัมฤทธิ์ สมรรถนะ คุณลักษณะ และความพร้อมศึกษาต่อ แล้วใช้ผลนิเทศและประเมินหลักสูตรปรับเนื้อหา เวลาเรียน และกิจกรรมให้เหมาะกับผู้เรียนแต่ละกลุ่ม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (308,140,2568,0,'{\"text\":\"โรงเรียนวิเคราะห์ความต้องการจำเป็นของผู้เรียน ชุมชน สังคม ท้องถิ่น และผู้มีส่วนเกี่ยวข้อง แล้วนำผลมาพัฒนาหลักสูตรให้ยืดหยุ่นและสอดคล้องกับหลักสูตรแกนกลาง ออกแบบการจัดการเรียนการสอนตามจุดมุ่งหมาย จัดทำแผนนิเทศ กำกับ ติดตาม และประเมินการใช้หลักสูตร ก่อนนำผลมาปรับปรุงหลักสูตรอย่างต่อเนื่อง\\n\\nคณะทำงานศึกษาหลักสูตรแกนกลาง มาตรฐานและตัวชี้วัด วิเคราะห์ข้อมูลผู้เรียนเป็นรายบุคคล รวมทั้งรับฟังความคิดเห็นจากผู้ปกครอง ชุมชน และหน่วยงานที่เกี่ยวข้อง ก่อนกำหนดโครงสร้างรายวิชาและแผนการเรียน โรงเรียนติดตามทั้งผลสัมฤทธิ์ สมรรถนะ คุณลักษณะ และความพร้อมศึกษาต่อ แล้วใช้ผลนิเทศและประเมินหลักสูตรปรับเนื้อหา เวลาเรียน และกิจกรรมให้เหมาะกับผู้เรียนแต่ละกลุ่ม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (309,141,2566,0,'{\"text\":\"กิจกรรมเสริมหลักสูตรกำหนดจากข้อมูลนักเรียนรายบุคคลและความคิดเห็นของผู้ปกครอง ชุมชน และผู้เกี่ยวข้อง มีวัตถุประสงค์และกรอบดำเนินงานชัดเจน จัดกิจกรรมทั้งรายบุคคลและกลุ่มอย่างหลากหลาย ท้าทาย และสร้างสรรค์ ครอบคลุมผู้เรียนทุกกลุ่มเป้าหมาย และมุ่งให้เกิดผลงานหรือการพัฒนาต่อยอดที่เห็นได้ชัด\\n\\nตัวอย่างกิจกรรมมีทั้งห้องเรียนพิเศษนวัตกรรมวิทยาศาสตร์และเทคโนโลยี (IST), Summer Camp เทคโนโลยี กิจกรรมแผนการเรียนวิทยาศาสตร์สุขภาพ การทดลองในห้องปฏิบัติการของมหาวิทยาลัยแม่โจ้ ค่ายฝึกปฏิบัติการทางการแพทย์และอนุรักษ์สิ่งแวดล้อมทางทะเล รวมถึงการฝึกประสบการณ์ในโรงพยาบาลและสถานประกอบการ กิจกรรมเหล่านี้ช่วยให้ผู้เรียนเห็นเส้นทางศึกษาต่อและอาชีพผ่านการลงมือทำจริง\"}',NULL,'2026-10-06 08:40:55');
