REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (312,142,2566,0,'{\"text\":\"โรงเรียนรับฟังความต้องการของครู นักเรียน และผู้เกี่ยวข้องก่อนออกแบบและจัดหาสื่อ เทคโนโลยี และแหล่งเรียนรู้ที่สอดคล้องกับหลักสูตร มีระบบบริการและบำรุงรักษา ส่งเสริมการใช้แหล่งเรียนรู้ทั้งในโรงเรียน ท้องถิ่น และชุมชน รวมถึงเผยแพร่สื่อหรือนวัตกรรมที่ได้รับการยอมรับ\\n\\nครูเลือกใช้สื่อให้สัมพันธ์กับมาตรฐานการเรียนรู้และรูปแบบกิจกรรม เช่น การเรียนรู้จากการปฏิบัติ โครงงาน การอภิปราย และการเรียนรู้แบบร่วมมือ พร้อมใช้ห้องเรียน ห้องปฏิบัติการ ห้องสมุด แหล่งเรียนรู้ในชุมชน และหน่วยงานภายนอก โรงเรียนประเมินความพึงพอใจและประโยชน์ของสื่อ ดูแลความพร้อมของอุปกรณ์ และนำผลประเมินไปวางแผนจัดหาและพัฒนาในปีถัดไป\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (313,142,2567,0,'{\"text\":\"โรงเรียนรับฟังความต้องการของครู นักเรียน และผู้เกี่ยวข้องก่อนออกแบบและจัดหาสื่อ เทคโนโลยี และแหล่งเรียนรู้ที่สอดคล้องกับหลักสูตร มีระบบบริการและบำรุงรักษา ส่งเสริมการใช้แหล่งเรียนรู้ทั้งในโรงเรียน ท้องถิ่น และชุมชน รวมถึงเผยแพร่สื่อหรือนวัตกรรมที่ได้รับการยอมรับ\\n\\nครูเลือกใช้สื่อให้สัมพันธ์กับมาตรฐานการเรียนรู้และรูปแบบกิจกรรม เช่น การเรียนรู้จากการปฏิบัติ โครงงาน การอภิปราย และการเรียนรู้แบบร่วมมือ พร้อมใช้ห้องเรียน ห้องปฏิบัติการ ห้องสมุด แหล่งเรียนรู้ในชุมชน และหน่วยงานภายนอก โรงเรียนประเมินความพึงพอใจและประโยชน์ของสื่อ ดูแลความพร้อมของอุปกรณ์ และนำผลประเมินไปวางแผนจัดหาและพัฒนาในปีถัดไป\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (314,142,2568,0,'{\"text\":\"โรงเรียนรับฟังความต้องการของครู นักเรียน และผู้เกี่ยวข้องก่อนออกแบบและจัดหาสื่อ เทคโนโลยี และแหล่งเรียนรู้ที่สอดคล้องกับหลักสูตร มีระบบบริการและบำรุงรักษา ส่งเสริมการใช้แหล่งเรียนรู้ทั้งในโรงเรียน ท้องถิ่น และชุมชน รวมถึงเผยแพร่สื่อหรือนวัตกรรมที่ได้รับการยอมรับ\\n\\nครูเลือกใช้สื่อให้สัมพันธ์กับมาตรฐานการเรียนรู้และรูปแบบกิจกรรม เช่น การเรียนรู้จากการปฏิบัติ โครงงาน การอภิปราย และการเรียนรู้แบบร่วมมือ พร้อมใช้ห้องเรียน ห้องปฏิบัติการ ห้องสมุด แหล่งเรียนรู้ในชุมชน และหน่วยงานภายนอก โรงเรียนประเมินความพึงพอใจและประโยชน์ของสื่อ ดูแลความพร้อมของอุปกรณ์ และนำผลประเมินไปวางแผนจัดหาและพัฒนาในปีถัดไป\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (315,143,2566,0,'{\"text\":\"ครูวิเคราะห์ผู้เรียนเป็นรายบุคคล กำหนดเป้าหมายการเรียนรู้ ออกแบบกิจกรรมที่เน้นการลงมือปฏิบัติและการมีส่วนร่วม เลือกใช้สื่อ แหล่งเรียนรู้ และเทคโนโลยีให้เหมาะกับเนื้อหาและความแตกต่างของผู้เรียน พร้อมกำหนดวิธีวัดและประเมินผลให้สอดคล้องกับจุดประสงค์\\n\\nแผนการจัดการเรียนรู้ระบุมาตรฐาน ตัวชี้วัด สมรรถนะ คุณลักษณะ ภาระงาน และเกณฑ์ประเมินอย่างสอดคล้องกัน ผู้เรียนได้รับโอกาสตั้งคำถาม สืบค้น ทดลอง ทำโครงงาน อภิปราย และนำเสนอผลงาน ครูปรับระดับความยากและวิธีช่วยเหลือตามข้อมูลรายบุคคล เพื่อให้ทั้งกลุ่มที่ต้องพัฒนา กลุ่มทั่วไป และกลุ่มศักยภาพสูงก้าวหน้าได้\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (316,143,2567,0,'{\"text\":\"ครูวิเคราะห์ผู้เรียนเป็นรายบุคคล กำหนดเป้าหมายการเรียนรู้ ออกแบบกิจกรรมที่เน้นการลงมือปฏิบัติและการมีส่วนร่วม เลือกใช้สื่อ แหล่งเรียนรู้ และเทคโนโลยีให้เหมาะกับเนื้อหาและความแตกต่างของผู้เรียน พร้อมกำหนดวิธีวัดและประเมินผลให้สอดคล้องกับจุดประสงค์\\n\\nแผนการจัดการเรียนรู้ระบุมาตรฐาน ตัวชี้วัด สมรรถนะ คุณลักษณะ ภาระงาน และเกณฑ์ประเมินอย่างสอดคล้องกัน ผู้เรียนได้รับโอกาสตั้งคำถาม สืบค้น ทดลอง ทำโครงงาน อภิปราย และนำเสนอผลงาน ครูปรับระดับความยากและวิธีช่วยเหลือตามข้อมูลรายบุคคล เพื่อให้ทั้งกลุ่มที่ต้องพัฒนา กลุ่มทั่วไป และกลุ่มศักยภาพสูงก้าวหน้าได้\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (317,143,2568,0,'{\"text\":\"ครูวิเคราะห์ผู้เรียนเป็นรายบุคคล กำหนดเป้าหมายการเรียนรู้ ออกแบบกิจกรรมที่เน้นการลงมือปฏิบัติและการมีส่วนร่วม เลือกใช้สื่อ แหล่งเรียนรู้ และเทคโนโลยีให้เหมาะกับเนื้อหาและความแตกต่างของผู้เรียน พร้อมกำหนดวิธีวัดและประเมินผลให้สอดคล้องกับจุดประสงค์\\n\\nแผนการจัดการเรียนรู้ระบุมาตรฐาน ตัวชี้วัด สมรรถนะ คุณลักษณะ ภาระงาน และเกณฑ์ประเมินอย่างสอดคล้องกัน ผู้เรียนได้รับโอกาสตั้งคำถาม สืบค้น ทดลอง ทำโครงงาน อภิปราย และนำเสนอผลงาน ครูปรับระดับความยากและวิธีช่วยเหลือตามข้อมูลรายบุคคล เพื่อให้ทั้งกลุ่มที่ต้องพัฒนา กลุ่มทั่วไป และกลุ่มศักยภาพสูงก้าวหน้าได้\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (318,144,2566,0,'{\"text\":\"การจัดชั้นเรียนส่งเสริมการทำงานเป็นกลุ่ม การแลกเปลี่ยนความคิดเห็น การใช้เทคโนโลยี การเรียนรู้จากภูมิปัญญาท้องถิ่น และการช่วยเหลือผู้เรียนที่ต้องการการพัฒนาเพิ่มเติม ครูใช้ผลการสังเกต การสะท้อนคิด และข้อเสนอแนะของผู้เรียนเพื่อปรับกิจกรรมและบรรยากาศการเรียนรู้\\n\\nครูสร้างข้อตกลงและบรรยากาศที่ปลอดภัย เปิดโอกาสให้ผู้เรียนแสดงความคิดเห็นและประเมินการเรียนรู้ของตนเอง ใช้ชิ้นงาน แบบสังเกต แบบทดสอบ และการสนทนาสะท้อนผลเป็นข้อมูล เมื่อพบข้อบกพร่องจะจัดการสอนซ่อมเสริม ปรับกลุ่มเรียนหรือกิจกรรม ส่วนผู้เรียนที่มีศักยภาพจะได้รับโจทย์ท้าทายและโอกาสเข้าร่วมการแข่งขัน\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (319,144,2567,0,'{\"text\":\"การจัดชั้นเรียนส่งเสริมการทำงานเป็นกลุ่ม การแลกเปลี่ยนความคิดเห็น การใช้เทคโนโลยี การเรียนรู้จากภูมิปัญญาท้องถิ่น และการช่วยเหลือผู้เรียนที่ต้องการการพัฒนาเพิ่มเติม ครูใช้ผลการสังเกต การสะท้อนคิด และข้อเสนอแนะของผู้เรียนเพื่อปรับกิจกรรมและบรรยากาศการเรียนรู้\\n\\nครูสร้างข้อตกลงและบรรยากาศที่ปลอดภัย เปิดโอกาสให้ผู้เรียนแสดงความคิดเห็นและประเมินการเรียนรู้ของตนเอง ใช้ชิ้นงาน แบบสังเกต แบบทดสอบ และการสนทนาสะท้อนผลเป็นข้อมูล เมื่อพบข้อบกพร่องจะจัดการสอนซ่อมเสริม ปรับกลุ่มเรียนหรือกิจกรรม ส่วนผู้เรียนที่มีศักยภาพจะได้รับโจทย์ท้าทายและโอกาสเข้าร่วมการแข่งขัน\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (320,144,2568,0,'{\"text\":\"การจัดชั้นเรียนส่งเสริมการทำงานเป็นกลุ่ม การแลกเปลี่ยนความคิดเห็น การใช้เทคโนโลยี การเรียนรู้จากภูมิปัญญาท้องถิ่น และการช่วยเหลือผู้เรียนที่ต้องการการพัฒนาเพิ่มเติม ครูใช้ผลการสังเกต การสะท้อนคิด และข้อเสนอแนะของผู้เรียนเพื่อปรับกิจกรรมและบรรยากาศการเรียนรู้\\n\\nครูสร้างข้อตกลงและบรรยากาศที่ปลอดภัย เปิดโอกาสให้ผู้เรียนแสดงความคิดเห็นและประเมินการเรียนรู้ของตนเอง ใช้ชิ้นงาน แบบสังเกต แบบทดสอบ และการสนทนาสะท้อนผลเป็นข้อมูล เมื่อพบข้อบกพร่องจะจัดการสอนซ่อมเสริม ปรับกลุ่มเรียนหรือกิจกรรม ส่วนผู้เรียนที่มีศักยภาพจะได้รับโจทย์ท้าทายและโอกาสเข้าร่วมการแข่งขัน\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (321,145,2566,0,'{\"text\":\"โรงเรียนพัฒนาสภาพแวดล้อมทางกายภาพและสังคมให้สะอาด ปลอดภัย และเอื้อต่อการเรียนรู้ จัดพื้นที่เรียนรู้ ห้องปฏิบัติการ ระบบสาธารณูปโภค และมาตรการดูแลช่วยเหลือนักเรียน พร้อมสร้างความรู้เรื่องการป้องกันตนเองจากสารเสพติด ปัญหาทางเพศ อบายมุข และภัยในรูปแบบต่าง ๆ\\n\\nการดำเนินงานครอบคลุมการสำรวจจุดเสี่ยง การดูแลอาคารและอุปกรณ์ ระบบสุขาภิบาล พื้นที่สีเขียว ห้องเรียนและห้องปฏิบัติการ ตลอดจนระบบดูแลช่วยเหลือนักเรียน โรงเรียนประสานครูที่ปรึกษา งานแนะแนว ผู้ปกครอง และเครือข่ายเพื่อเฝ้าระวังสุขภาพกาย สุขภาพจิต พฤติกรรมเสี่ยง และภัยออนไลน์ พร้อมจัดกิจกรรมให้ผู้เรียนรู้จักขอความช่วยเหลือและป้องกันตนเอง\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (322,145,2567,0,'{\"text\":\"โรงเรียนพัฒนาสภาพแวดล้อมทางกายภาพและสังคมให้สะอาด ปลอดภัย และเอื้อต่อการเรียนรู้ จัดพื้นที่เรียนรู้ ห้องปฏิบัติการ ระบบสาธารณูปโภค และมาตรการดูแลช่วยเหลือนักเรียน พร้อมสร้างความรู้เรื่องการป้องกันตนเองจากสารเสพติด ปัญหาทางเพศ อบายมุข และภัยในรูปแบบต่าง ๆ\\n\\nการดำเนินงานครอบคลุมการสำรวจจุดเสี่ยง การดูแลอาคารและอุปกรณ์ ระบบสุขาภิบาล พื้นที่สีเขียว ห้องเรียนและห้องปฏิบัติการ ตลอดจนระบบดูแลช่วยเหลือนักเรียน โรงเรียนประสานครูที่ปรึกษา งานแนะแนว ผู้ปกครอง และเครือข่ายเพื่อเฝ้าระวังสุขภาพกาย สุขภาพจิต พฤติกรรมเสี่ยง และภัยออนไลน์ พร้อมจัดกิจกรรมให้ผู้เรียนรู้จักขอความช่วยเหลือและป้องกันตนเอง\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (323,145,2568,0,'{\"text\":\"โรงเรียนพัฒนาสภาพแวดล้อมทางกายภาพและสังคมให้สะอาด ปลอดภัย และเอื้อต่อการเรียนรู้ จัดพื้นที่เรียนรู้ ห้องปฏิบัติการ ระบบสาธารณูปโภค และมาตรการดูแลช่วยเหลือนักเรียน พร้อมสร้างความรู้เรื่องการป้องกันตนเองจากสารเสพติด ปัญหาทางเพศ อบายมุข และภัยในรูปแบบต่าง ๆ\\n\\nการดำเนินงานครอบคลุมการสำรวจจุดเสี่ยง การดูแลอาคารและอุปกรณ์ ระบบสุขาภิบาล พื้นที่สีเขียว ห้องเรียนและห้องปฏิบัติการ ตลอดจนระบบดูแลช่วยเหลือนักเรียน โรงเรียนประสานครูที่ปรึกษา งานแนะแนว ผู้ปกครอง และเครือข่ายเพื่อเฝ้าระวังสุขภาพกาย สุขภาพจิต พฤติกรรมเสี่ยง และภัยออนไลน์ พร้อมจัดกิจกรรมให้ผู้เรียนรู้จักขอความช่วยเหลือและป้องกันตนเอง\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (324,146,2566,0,'{\"text\":\"โรงเรียนบริหารงบประมาณ การเงิน พัสดุ และสินทรัพย์ให้สอดคล้องกับแผนพัฒนาคุณภาพและแผนปฏิบัติการประจำปี โดยยึดความถูกต้อง โปร่งใส ตรวจสอบได้ และความคุ้มค่า สนับสนุนทรัพยากรต่อภารกิจหลักทั้งด้านผู้เรียน บุคลากร หลักสูตร เทคโนโลยี และสภาพแวดล้อม\\n\\nขั้นวางแผนนำกลยุทธ์และมาตรฐานของโรงเรียนมาจัดทำแผนปฏิบัติการ โดยแต่ละโครงการระบุวัตถุประสงค์ ตัวชี้วัด ผู้รับผิดชอบ และงบประมาณชัดเจน ระหว่างดำเนินงานมีการควบคุมเอกสาร การจัดซื้อจัดจ้าง และการใช้ทรัพย์สินตามระเบียบ เมื่อสิ้นโครงการจะประเมินผลและความคุ้มค่า เพื่อนำข้อมูลไปจัดลำดับความสำคัญของงบประมาณรอบใหม่\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (325,146,2567,0,'{\"text\":\"โรงเรียนบริหารงบประมาณ การเงิน พัสดุ และสินทรัพย์ให้สอดคล้องกับแผนพัฒนาคุณภาพและแผนปฏิบัติการประจำปี โดยยึดความถูกต้อง โปร่งใส ตรวจสอบได้ และความคุ้มค่า สนับสนุนทรัพยากรต่อภารกิจหลักทั้งด้านผู้เรียน บุคลากร หลักสูตร เทคโนโลยี และสภาพแวดล้อม\\n\\nขั้นวางแผนนำกลยุทธ์และมาตรฐานของโรงเรียนมาจัดทำแผนปฏิบัติการ โดยแต่ละโครงการระบุวัตถุประสงค์ ตัวชี้วัด ผู้รับผิดชอบ และงบประมาณชัดเจน ระหว่างดำเนินงานมีการควบคุมเอกสาร การจัดซื้อจัดจ้าง และการใช้ทรัพย์สินตามระเบียบ เมื่อสิ้นโครงการจะประเมินผลและความคุ้มค่า เพื่อนำข้อมูลไปจัดลำดับความสำคัญของงบประมาณรอบใหม่\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (326,146,2568,0,'{\"text\":\"โรงเรียนบริหารงบประมาณ การเงิน พัสดุ และสินทรัพย์ให้สอดคล้องกับแผนพัฒนาคุณภาพและแผนปฏิบัติการประจำปี โดยยึดความถูกต้อง โปร่งใส ตรวจสอบได้ และความคุ้มค่า สนับสนุนทรัพยากรต่อภารกิจหลักทั้งด้านผู้เรียน บุคลากร หลักสูตร เทคโนโลยี และสภาพแวดล้อม\\n\\nขั้นวางแผนนำกลยุทธ์และมาตรฐานของโรงเรียนมาจัดทำแผนปฏิบัติการ โดยแต่ละโครงการระบุวัตถุประสงค์ ตัวชี้วัด ผู้รับผิดชอบ และงบประมาณชัดเจน ระหว่างดำเนินงานมีการควบคุมเอกสาร การจัดซื้อจัดจ้าง และการใช้ทรัพย์สินตามระเบียบ เมื่อสิ้นโครงการจะประเมินผลและความคุ้มค่า เพื่อนำข้อมูลไปจัดลำดับความสำคัญของงบประมาณรอบใหม่\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (327,147,2566,0,'{\"text\":\"โรงเรียนใช้ผลการทดสอบระดับชาติ ผลสัมฤทธิ์ตามหลักสูตร ผลการอ่าน คิดวิเคราะห์และเขียน ตลอดจนข้อมูลรายบุคคลของผู้เรียนมาวิเคราะห์จุดแข็งและประเด็นพัฒนา จัดกิจกรรมยกระดับผลสัมฤทธิ์ การสอนซ่อมเสริม การแนะแนว และกิจกรรมส่งเสริมความเป็นเลิศตามศักยภาพ\\n\\nสำหรับ O-NET โรงเรียนนำผลระดับ ม.3 และ ม.6 มาวิเคราะห์รายวิชา รายมาตรฐาน ตัวชี้วัด และรายบุคคล แล้วแบ่งผู้เรียนเป็นกลุ่มที่ต้องพัฒนาเร่งด่วน กลุ่มที่ควรส่งเสริมเพิ่มเติม และกลุ่มศักยภาพสูง มีโครงการพัฒนาผลสัมฤทธิ์ กิจกรรมเตรียมความพร้อมสู่มหาวิทยาลัย การนิเทศการสอน และการทดสอบ Pre-test/Post-test รวมถึงแนวทาง SANSAI O-NET SMART ที่ใช้ข้อมูลร่วมกับการเรียนรู้เชิงรุกเพื่อแก้จุดอ่อนอย่างตรงจุด\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (328,147,2567,0,'{\"text\":\"โรงเรียนใช้ผลการทดสอบระดับชาติ ผลสัมฤทธิ์ตามหลักสูตร ผลการอ่าน คิดวิเคราะห์และเขียน ตลอดจนข้อมูลรายบุคคลของผู้เรียนมาวิเคราะห์จุดแข็งและประเด็นพัฒนา จัดกิจกรรมยกระดับผลสัมฤทธิ์ การสอนซ่อมเสริม การแนะแนว และกิจกรรมส่งเสริมความเป็นเลิศตามศักยภาพ\\n\\nสำหรับ O-NET โรงเรียนนำผลระดับ ม.3 และ ม.6 มาวิเคราะห์รายวิชา รายมาตรฐาน ตัวชี้วัด และรายบุคคล แล้วแบ่งผู้เรียนเป็นกลุ่มที่ต้องพัฒนาเร่งด่วน กลุ่มที่ควรส่งเสริมเพิ่มเติม และกลุ่มศักยภาพสูง มีโครงการพัฒนาผลสัมฤทธิ์ กิจกรรมเตรียมความพร้อมสู่มหาวิทยาลัย การนิเทศการสอน และการทดสอบ Pre-test/Post-test รวมถึงแนวทาง SANSAI O-NET SMART ที่ใช้ข้อมูลร่วมกับการเรียนรู้เชิงรุกเพื่อแก้จุดอ่อนอย่างตรงจุด\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (329,147,2568,0,'{\"text\":\"โรงเรียนใช้ผลการทดสอบระดับชาติ ผลสัมฤทธิ์ตามหลักสูตร ผลการอ่าน คิดวิเคราะห์และเขียน ตลอดจนข้อมูลรายบุคคลของผู้เรียนมาวิเคราะห์จุดแข็งและประเด็นพัฒนา จัดกิจกรรมยกระดับผลสัมฤทธิ์ การสอนซ่อมเสริม การแนะแนว และกิจกรรมส่งเสริมความเป็นเลิศตามศักยภาพ\\n\\nสำหรับ O-NET โรงเรียนนำผลระดับ ม.3 และ ม.6 มาวิเคราะห์รายวิชา รายมาตรฐาน ตัวชี้วัด และรายบุคคล แล้วแบ่งผู้เรียนเป็นกลุ่มที่ต้องพัฒนาเร่งด่วน กลุ่มที่ควรส่งเสริมเพิ่มเติม และกลุ่มศักยภาพสูง มีโครงการพัฒนาผลสัมฤทธิ์ กิจกรรมเตรียมความพร้อมสู่มหาวิทยาลัย การนิเทศการสอน และการทดสอบ Pre-test/Post-test รวมถึงแนวทาง SANSAI O-NET SMART ที่ใช้ข้อมูลร่วมกับการเรียนรู้เชิงรุกเพื่อแก้จุดอ่อนอย่างตรงจุด\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (330,148,2566,0,'{\"text\":\"โรงเรียนส่งเสริมการอ่านและเขียนภาษาไทย การใช้ภาษาอังกฤษเพื่อการสื่อสาร การคิดคำนวณ การคิดวิเคราะห์ การแก้ปัญหา และการศึกษาค้นคว้าด้วยตนเอง ผ่านกิจกรรมการเรียนรู้เชิงรุก โครงงาน การแข่งขัน และการสร้างนวัตกรรม โดยสนับสนุนให้ผู้เรียนอธิบายกระบวนการทำงาน นำผลงานไปใช้ และเผยแพร่ได้\\n\\nโรงเรียนติดตามผลการอ่าน-เขียนภาษาไทย ทักษะภาษาอังกฤษ รายวิชาการศึกษาค้นคว้าด้วยตนเอง (IS) การอ่านคิดวิเคราะห์และเขียน และความสามารถด้านเทคโนโลยีอย่างต่อเนื่อง ผู้เรียนได้สร้างชิ้นงานและโครงงาน อธิบายขั้นตอน ทดลองแก้ปัญหา และนำเสนอในเวทีทั้งภายในและภายนอก ผลงานการแข่งขันระดับจังหวัด ภูมิภาค ชาติ และนานาชาติถูกใช้เป็นหลักฐานประกอบการประเมินและเป็นแรงจูงใจในการพัฒนาต่อ\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (331,148,2567,0,'{\"text\":\"โรงเรียนส่งเสริมการอ่านและเขียนภาษาไทย การใช้ภาษาอังกฤษเพื่อการสื่อสาร การคิดคำนวณ การคิดวิเคราะห์ การแก้ปัญหา และการศึกษาค้นคว้าด้วยตนเอง ผ่านกิจกรรมการเรียนรู้เชิงรุก โครงงาน การแข่งขัน และการสร้างนวัตกรรม โดยสนับสนุนให้ผู้เรียนอธิบายกระบวนการทำงาน นำผลงานไปใช้ และเผยแพร่ได้\\n\\nโรงเรียนติดตามผลการอ่าน-เขียนภาษาไทย ทักษะภาษาอังกฤษ รายวิชาการศึกษาค้นคว้าด้วยตนเอง (IS) การอ่านคิดวิเคราะห์และเขียน และความสามารถด้านเทคโนโลยีอย่างต่อเนื่อง ผู้เรียนได้สร้างชิ้นงานและโครงงาน อธิบายขั้นตอน ทดลองแก้ปัญหา และนำเสนอในเวทีทั้งภายในและภายนอก ผลงานการแข่งขันระดับจังหวัด ภูมิภาค ชาติ และนานาชาติถูกใช้เป็นหลักฐานประกอบการประเมินและเป็นแรงจูงใจในการพัฒนาต่อ\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (332,148,2568,0,'{\"text\":\"โรงเรียนส่งเสริมการอ่านและเขียนภาษาไทย การใช้ภาษาอังกฤษเพื่อการสื่อสาร การคิดคำนวณ การคิดวิเคราะห์ การแก้ปัญหา และการศึกษาค้นคว้าด้วยตนเอง ผ่านกิจกรรมการเรียนรู้เชิงรุก โครงงาน การแข่งขัน และการสร้างนวัตกรรม โดยสนับสนุนให้ผู้เรียนอธิบายกระบวนการทำงาน นำผลงานไปใช้ และเผยแพร่ได้\\n\\nโรงเรียนติดตามผลการอ่าน-เขียนภาษาไทย ทักษะภาษาอังกฤษ รายวิชาการศึกษาค้นคว้าด้วยตนเอง (IS) การอ่านคิดวิเคราะห์และเขียน และความสามารถด้านเทคโนโลยีอย่างต่อเนื่อง ผู้เรียนได้สร้างชิ้นงานและโครงงาน อธิบายขั้นตอน ทดลองแก้ปัญหา และนำเสนอในเวทีทั้งภายในและภายนอก ผลงานการแข่งขันระดับจังหวัด ภูมิภาค ชาติ และนานาชาติถูกใช้เป็นหลักฐานประกอบการประเมินและเป็นแรงจูงใจในการพัฒนาต่อ\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (333,149,2566,0,'{\"text\":\"โรงเรียนสร้างและพัฒนาแนวทาง ระเบียบ และเครื่องมือวัดประเมินผลที่หลากหลายและสอดคล้องกับสิ่งที่ต้องการวัด มีส่วนร่วมจากครู นักเรียน ผู้ปกครอง และผู้เกี่ยวข้อง จัดเก็บข้อมูลอย่างเป็นระบบ และจัดทำเอกสารประกอบการวัดประเมินผลเพื่อใช้ติดตามพัฒนาการของผู้เรียน\\n\\nเครื่องมือครอบคลุมแบบทดสอบ ภาระงาน ชิ้นงาน โครงงาน แบบสังเกต และเกณฑ์รูบริก โดยกำหนดให้สัมพันธ์กับมาตรฐาน ตัวชี้วัด และสมรรถนะที่ต้องการ โรงเรียนตรวจสอบคุณภาพเครื่องมือ จัดเก็บคะแนนและหลักฐานอย่างเป็นระบบ และสื่อสารเกณฑ์ให้ผู้เรียนทราบ รวมทั้งเปิดโอกาสให้ผู้เรียนประเมินตนเองและใช้ข้อมูลจากผู้ปกครองประกอบเมื่อเหมาะสม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (334,149,2567,0,'{\"text\":\"โรงเรียนสร้างและพัฒนาแนวทาง ระเบียบ และเครื่องมือวัดประเมินผลที่หลากหลายและสอดคล้องกับสิ่งที่ต้องการวัด มีส่วนร่วมจากครู นักเรียน ผู้ปกครอง และผู้เกี่ยวข้อง จัดเก็บข้อมูลอย่างเป็นระบบ และจัดทำเอกสารประกอบการวัดประเมินผลเพื่อใช้ติดตามพัฒนาการของผู้เรียน\\n\\nเครื่องมือครอบคลุมแบบทดสอบ ภาระงาน ชิ้นงาน โครงงาน แบบสังเกต และเกณฑ์รูบริก โดยกำหนดให้สัมพันธ์กับมาตรฐาน ตัวชี้วัด และสมรรถนะที่ต้องการ โรงเรียนตรวจสอบคุณภาพเครื่องมือ จัดเก็บคะแนนและหลักฐานอย่างเป็นระบบ และสื่อสารเกณฑ์ให้ผู้เรียนทราบ รวมทั้งเปิดโอกาสให้ผู้เรียนประเมินตนเองและใช้ข้อมูลจากผู้ปกครองประกอบเมื่อเหมาะสม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (335,149,2568,0,'{\"text\":\"โรงเรียนสร้างและพัฒนาแนวทาง ระเบียบ และเครื่องมือวัดประเมินผลที่หลากหลายและสอดคล้องกับสิ่งที่ต้องการวัด มีส่วนร่วมจากครู นักเรียน ผู้ปกครอง และผู้เกี่ยวข้อง จัดเก็บข้อมูลอย่างเป็นระบบ และจัดทำเอกสารประกอบการวัดประเมินผลเพื่อใช้ติดตามพัฒนาการของผู้เรียน\\n\\nเครื่องมือครอบคลุมแบบทดสอบ ภาระงาน ชิ้นงาน โครงงาน แบบสังเกต และเกณฑ์รูบริก โดยกำหนดให้สัมพันธ์กับมาตรฐาน ตัวชี้วัด และสมรรถนะที่ต้องการ โรงเรียนตรวจสอบคุณภาพเครื่องมือ จัดเก็บคะแนนและหลักฐานอย่างเป็นระบบ และสื่อสารเกณฑ์ให้ผู้เรียนทราบ รวมทั้งเปิดโอกาสให้ผู้เรียนประเมินตนเองและใช้ข้อมูลจากผู้ปกครองประกอบเมื่อเหมาะสม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (336,150,2566,0,'{\"text\":\"ครูและผู้บริหารนำผลการประเมินก่อนเรียน ระหว่างเรียน และหลังเรียนมาวิเคราะห์แนวโน้ม ให้ข้อมูลย้อนกลับแก่ผู้เรียน วางแผนซ่อมเสริมหรือส่งเสริมความสามารถเฉพาะด้าน ปรับแผนการสอน และรายงานผลต่อผู้ปกครอง เพื่อให้การพัฒนาผู้เรียนต่อเนื่องและตอบสนองความแตกต่างรายบุคคล\\n\\nผลประเมินถูกนำไปจัดกลุ่มและวางแผนช่วยเหลือรายบุคคล ไม่ใช้เพียงตัดสินผลการเรียน ครูวิเคราะห์ข้อผิดพลาดและให้ข้อมูลย้อนกลับที่ระบุสิ่งที่ทำได้ สิ่งที่ต้องปรับ และแนวทางฝึกเพิ่มเติม จากนั้นติดตามผลหลังการซ่อมเสริมหรือส่งเสริม พร้อมใช้ข้อมูลระดับห้องเรียนและระดับโรงเรียนกำหนดโครงการและเป้าหมายในปีถัดไป\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (337,150,2567,0,'{\"text\":\"ครูและผู้บริหารนำผลการประเมินก่อนเรียน ระหว่างเรียน และหลังเรียนมาวิเคราะห์แนวโน้ม ให้ข้อมูลย้อนกลับแก่ผู้เรียน วางแผนซ่อมเสริมหรือส่งเสริมความสามารถเฉพาะด้าน ปรับแผนการสอน และรายงานผลต่อผู้ปกครอง เพื่อให้การพัฒนาผู้เรียนต่อเนื่องและตอบสนองความแตกต่างรายบุคคล\\n\\nผลประเมินถูกนำไปจัดกลุ่มและวางแผนช่วยเหลือรายบุคคล ไม่ใช้เพียงตัดสินผลการเรียน ครูวิเคราะห์ข้อผิดพลาดและให้ข้อมูลย้อนกลับที่ระบุสิ่งที่ทำได้ สิ่งที่ต้องปรับ และแนวทางฝึกเพิ่มเติม จากนั้นติดตามผลหลังการซ่อมเสริมหรือส่งเสริม พร้อมใช้ข้อมูลระดับห้องเรียนและระดับโรงเรียนกำหนดโครงการและเป้าหมายในปีถัดไป\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (338,150,2568,0,'{\"text\":\"ครูและผู้บริหารนำผลการประเมินก่อนเรียน ระหว่างเรียน และหลังเรียนมาวิเคราะห์แนวโน้ม ให้ข้อมูลย้อนกลับแก่ผู้เรียน วางแผนซ่อมเสริมหรือส่งเสริมความสามารถเฉพาะด้าน ปรับแผนการสอน และรายงานผลต่อผู้ปกครอง เพื่อให้การพัฒนาผู้เรียนต่อเนื่องและตอบสนองความแตกต่างรายบุคคล\\n\\nผลประเมินถูกนำไปจัดกลุ่มและวางแผนช่วยเหลือรายบุคคล ไม่ใช้เพียงตัดสินผลการเรียน ครูวิเคราะห์ข้อผิดพลาดและให้ข้อมูลย้อนกลับที่ระบุสิ่งที่ทำได้ สิ่งที่ต้องปรับ และแนวทางฝึกเพิ่มเติม จากนั้นติดตามผลหลังการซ่อมเสริมหรือส่งเสริม พร้อมใช้ข้อมูลระดับห้องเรียนและระดับโรงเรียนกำหนดโครงการและเป้าหมายในปีถัดไป\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (339,151,2566,0,'{\"text\":\"โรงเรียนปลูกฝังความรักชาติ ศาสน์ กษัตริย์ ความซื่อสัตย์ มีวินัย ใฝ่เรียนรู้ อยู่อย่างพอเพียง มุ่งมั่นในการทำงาน รักความเป็นไทย และมีจิตสาธารณะ ผ่านการเรียนรู้ กิจกรรมพัฒนาผู้เรียน กิจกรรมสภานักเรียน และการบริการชุมชน โดยเน้นประโยชน์ส่วนรวมและการอยู่ร่วมกันอย่างรับผิดชอบ\\n\\nโรงเรียนติดตามคุณลักษณะอันพึงประสงค์ทั้ง 8 ด้านผ่านการสังเกตพฤติกรรม การเรียนรายวิชา และกิจกรรมพัฒนาผู้เรียน มีกิจกรรมประชาธิปไตยและการเลือกตั้งสภาผู้แทนนักเรียน กิจกรรมป้องกันการทุจริต งานจิตอาสา และการบริจาคโลหิต โดยมุ่งให้ผู้เรียนมีส่วนร่วม ตัดสินใจอย่างรับผิดชอบ เคารพกติกา และเห็นคุณค่าของการช่วยเหลือส่วนรวม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (340,151,2567,0,'{\"text\":\"โรงเรียนปลูกฝังความรักชาติ ศาสน์ กษัตริย์ ความซื่อสัตย์ มีวินัย ใฝ่เรียนรู้ อยู่อย่างพอเพียง มุ่งมั่นในการทำงาน รักความเป็นไทย และมีจิตสาธารณะ ผ่านการเรียนรู้ กิจกรรมพัฒนาผู้เรียน กิจกรรมสภานักเรียน และการบริการชุมชน โดยเน้นประโยชน์ส่วนรวมและการอยู่ร่วมกันอย่างรับผิดชอบ\\n\\nโรงเรียนติดตามคุณลักษณะอันพึงประสงค์ทั้ง 8 ด้านผ่านการสังเกตพฤติกรรม การเรียนรายวิชา และกิจกรรมพัฒนาผู้เรียน มีกิจกรรมประชาธิปไตยและการเลือกตั้งสภาผู้แทนนักเรียน กิจกรรมป้องกันการทุจริต งานจิตอาสา และการบริจาคโลหิต โดยมุ่งให้ผู้เรียนมีส่วนร่วม ตัดสินใจอย่างรับผิดชอบ เคารพกติกา และเห็นคุณค่าของการช่วยเหลือส่วนรวม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (341,151,2568,0,'{\"text\":\"โรงเรียนปลูกฝังความรักชาติ ศาสน์ กษัตริย์ ความซื่อสัตย์ มีวินัย ใฝ่เรียนรู้ อยู่อย่างพอเพียง มุ่งมั่นในการทำงาน รักความเป็นไทย และมีจิตสาธารณะ ผ่านการเรียนรู้ กิจกรรมพัฒนาผู้เรียน กิจกรรมสภานักเรียน และการบริการชุมชน โดยเน้นประโยชน์ส่วนรวมและการอยู่ร่วมกันอย่างรับผิดชอบ\\n\\nโรงเรียนติดตามคุณลักษณะอันพึงประสงค์ทั้ง 8 ด้านผ่านการสังเกตพฤติกรรม การเรียนรายวิชา และกิจกรรมพัฒนาผู้เรียน มีกิจกรรมประชาธิปไตยและการเลือกตั้งสภาผู้แทนนักเรียน กิจกรรมป้องกันการทุจริต งานจิตอาสา และการบริจาคโลหิต โดยมุ่งให้ผู้เรียนมีส่วนร่วม ตัดสินใจอย่างรับผิดชอบ เคารพกติกา และเห็นคุณค่าของการช่วยเหลือส่วนรวม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (342,152,2566,0,'{\"text\":\"ผู้เรียนมีส่วนร่วมในกิจกรรมอนุรักษ์ทรัพยากรธรรมชาติและสิ่งแวดล้อม เรียนรู้ภูมิปัญญาท้องถิ่น และนำความรู้ไปประยุกต์ใช้ในชีวิตประจำวัน โรงเรียนเชื่อมโยงกิจกรรมกับงานสวนพฤกษศาสตร์โรงเรียน แหล่งเรียนรู้ชุมชน และการบูรณาการในกลุ่มสาระการเรียนรู้\\n\\nกิจกรรมเชื่อมการสำรวจพรรณไม้ การจัดทำข้อมูลพืช การดูแลพื้นที่สีเขียว และการศึกษาความสัมพันธ์ระหว่างพืชกับวัฒนธรรมชุมชนเข้ากับรายวิชาต่าง ๆ ผู้เรียนได้เรียนรู้จากของจริง บันทึกข้อมูล สื่อสารผล และนำความรู้ไปใช้ในโรงเรียนหรือครอบครัว รวมถึงทำงานร่วมกับมหาวิทยาลัยและหน่วยงานด้านพฤกษศาสตร์\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (343,152,2567,0,'{\"text\":\"ผู้เรียนมีส่วนร่วมในกิจกรรมอนุรักษ์ทรัพยากรธรรมชาติและสิ่งแวดล้อม เรียนรู้ภูมิปัญญาท้องถิ่น และนำความรู้ไปประยุกต์ใช้ในชีวิตประจำวัน โรงเรียนเชื่อมโยงกิจกรรมกับงานสวนพฤกษศาสตร์โรงเรียน แหล่งเรียนรู้ชุมชน และการบูรณาการในกลุ่มสาระการเรียนรู้\\n\\nกิจกรรมเชื่อมการสำรวจพรรณไม้ การจัดทำข้อมูลพืช การดูแลพื้นที่สีเขียว และการศึกษาความสัมพันธ์ระหว่างพืชกับวัฒนธรรมชุมชนเข้ากับรายวิชาต่าง ๆ ผู้เรียนได้เรียนรู้จากของจริง บันทึกข้อมูล สื่อสารผล และนำความรู้ไปใช้ในโรงเรียนหรือครอบครัว รวมถึงทำงานร่วมกับมหาวิทยาลัยและหน่วยงานด้านพฤกษศาสตร์\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (344,152,2568,0,'{\"text\":\"ผู้เรียนมีส่วนร่วมในกิจกรรมอนุรักษ์ทรัพยากรธรรมชาติและสิ่งแวดล้อม เรียนรู้ภูมิปัญญาท้องถิ่น และนำความรู้ไปประยุกต์ใช้ในชีวิตประจำวัน โรงเรียนเชื่อมโยงกิจกรรมกับงานสวนพฤกษศาสตร์โรงเรียน แหล่งเรียนรู้ชุมชน และการบูรณาการในกลุ่มสาระการเรียนรู้\\n\\nกิจกรรมเชื่อมการสำรวจพรรณไม้ การจัดทำข้อมูลพืช การดูแลพื้นที่สีเขียว และการศึกษาความสัมพันธ์ระหว่างพืชกับวัฒนธรรมชุมชนเข้ากับรายวิชาต่าง ๆ ผู้เรียนได้เรียนรู้จากของจริง บันทึกข้อมูล สื่อสารผล และนำความรู้ไปใช้ในโรงเรียนหรือครอบครัว รวมถึงทำงานร่วมกับมหาวิทยาลัยและหน่วยงานด้านพฤกษศาสตร์\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (345,153,2566,0,'{\"text\":\"กิจกรรมการเรียนรู้และกิจกรรมพัฒนาผู้เรียนส่งเสริมการยอมรับเหตุผลและความคิดเห็นที่แตกต่าง การทำงานเป็นทีม ความรับผิดชอบ ความมุ่งมั่น ความมั่นใจ และเจตคติที่ดีต่อการเรียน ควบคู่กับการดูแลสุขภาพกาย สุขภาพจิต และทักษะการป้องกันตนเองจากความเสี่ยงต่าง ๆ\\n\\nโรงเรียนใช้ข้อมูลการเข้าร่วมกิจกรรม ผลสมรรถภาพทางกาย สุขภาพจิต และพฤติกรรมไม่พึงประสงค์ประกอบการดูแลผู้เรียน ครูที่ปรึกษา งานแนะแนว และงานกิจการนักเรียนร่วมติดตาม ช่วยเหลือ และประสานผู้ปกครอง กิจกรรมกลุ่มและโครงงานยังเปิดโอกาสให้ผู้เรียนแบ่งบทบาท รับฟังเหตุผล แก้ความขัดแย้ง และรับผิดชอบต่อผลของทีม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (346,153,2567,0,'{\"text\":\"กิจกรรมการเรียนรู้และกิจกรรมพัฒนาผู้เรียนส่งเสริมการยอมรับเหตุผลและความคิดเห็นที่แตกต่าง การทำงานเป็นทีม ความรับผิดชอบ ความมุ่งมั่น ความมั่นใจ และเจตคติที่ดีต่อการเรียน ควบคู่กับการดูแลสุขภาพกาย สุขภาพจิต และทักษะการป้องกันตนเองจากความเสี่ยงต่าง ๆ\\n\\nโรงเรียนใช้ข้อมูลการเข้าร่วมกิจกรรม ผลสมรรถภาพทางกาย สุขภาพจิต และพฤติกรรมไม่พึงประสงค์ประกอบการดูแลผู้เรียน ครูที่ปรึกษา งานแนะแนว และงานกิจการนักเรียนร่วมติดตาม ช่วยเหลือ และประสานผู้ปกครอง กิจกรรมกลุ่มและโครงงานยังเปิดโอกาสให้ผู้เรียนแบ่งบทบาท รับฟังเหตุผล แก้ความขัดแย้ง และรับผิดชอบต่อผลของทีม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (347,153,2568,0,'{\"text\":\"กิจกรรมการเรียนรู้และกิจกรรมพัฒนาผู้เรียนส่งเสริมการยอมรับเหตุผลและความคิดเห็นที่แตกต่าง การทำงานเป็นทีม ความรับผิดชอบ ความมุ่งมั่น ความมั่นใจ และเจตคติที่ดีต่อการเรียน ควบคู่กับการดูแลสุขภาพกาย สุขภาพจิต และทักษะการป้องกันตนเองจากความเสี่ยงต่าง ๆ\\n\\nโรงเรียนใช้ข้อมูลการเข้าร่วมกิจกรรม ผลสมรรถภาพทางกาย สุขภาพจิต และพฤติกรรมไม่พึงประสงค์ประกอบการดูแลผู้เรียน ครูที่ปรึกษา งานแนะแนว และงานกิจการนักเรียนร่วมติดตาม ช่วยเหลือ และประสานผู้ปกครอง กิจกรรมกลุ่มและโครงงานยังเปิดโอกาสให้ผู้เรียนแบ่งบทบาท รับฟังเหตุผล แก้ความขัดแย้ง และรับผิดชอบต่อผลของทีม\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (348,154,2566,0,'{\"text\":\"โรงเรียนน้อมนำพระราชดำริดำเนินงานสวนพฤกษศาสตร์โรงเรียน เพื่อสร้างจิตสำนึกด้านการอนุรักษ์และพัฒนาสถานศึกษาเป็นแหล่งเรียนรู้ธรรมชาติวิทยา ใช้ BANCHUEN Model และ PDCA ขับเคลื่อนอย่างเป็นระบบ บูรณาการกับการจัดการเรียนรู้ทุกกลุ่มสาระ และร่วมมือกับเครือข่าย เช่น มหาวิทยาลัยแม่โจ้ มหาวิทยาลัยเชียงใหม่ และสวนพฤกษศาสตร์สมเด็จพระนางเจ้าสิริกิติ์\\n\\nโครงการเป็นส่วนหนึ่งของโครงการอนุรักษ์พันธุกรรมพืชอันเนื่องมาจากพระราชดำริ (อพ.สธ.) โรงเรียนจัดแผนงาน ผู้รับผิดชอบ และงบประมาณผ่านกลุ่มบริหารวิชาการ ใช้พรรณไม้ในพื้นที่เป็นฐานการเรียนรู้ และได้รับคำปรึกษาจากเครือข่ายผู้เชี่ยวชาญ ผู้เรียนมีส่วนร่วมสำรวจ จำแนก บันทึก และสื่อสารข้อมูลพืช ผลการดำเนินงานนำไปสู่ผลงานของนักเรียนและการได้รับพระราชทานป้ายสนองพระราชดำริ\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (349,154,2567,0,'{\"text\":\"โรงเรียนน้อมนำพระราชดำริดำเนินงานสวนพฤกษศาสตร์โรงเรียน เพื่อสร้างจิตสำนึกด้านการอนุรักษ์และพัฒนาสถานศึกษาเป็นแหล่งเรียนรู้ธรรมชาติวิทยา ใช้ BANCHUEN Model และ PDCA ขับเคลื่อนอย่างเป็นระบบ บูรณาการกับการจัดการเรียนรู้ทุกกลุ่มสาระ และร่วมมือกับเครือข่าย เช่น มหาวิทยาลัยแม่โจ้ มหาวิทยาลัยเชียงใหม่ และสวนพฤกษศาสตร์สมเด็จพระนางเจ้าสิริกิติ์\\n\\nโครงการเป็นส่วนหนึ่งของโครงการอนุรักษ์พันธุกรรมพืชอันเนื่องมาจากพระราชดำริ (อพ.สธ.) โรงเรียนจัดแผนงาน ผู้รับผิดชอบ และงบประมาณผ่านกลุ่มบริหารวิชาการ ใช้พรรณไม้ในพื้นที่เป็นฐานการเรียนรู้ และได้รับคำปรึกษาจากเครือข่ายผู้เชี่ยวชาญ ผู้เรียนมีส่วนร่วมสำรวจ จำแนก บันทึก และสื่อสารข้อมูลพืช ผลการดำเนินงานนำไปสู่ผลงานของนักเรียนและการได้รับพระราชทานป้ายสนองพระราชดำริ\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (350,154,2568,0,'{\"text\":\"โรงเรียนน้อมนำพระราชดำริดำเนินงานสวนพฤกษศาสตร์โรงเรียน เพื่อสร้างจิตสำนึกด้านการอนุรักษ์และพัฒนาสถานศึกษาเป็นแหล่งเรียนรู้ธรรมชาติวิทยา ใช้ BANCHUEN Model และ PDCA ขับเคลื่อนอย่างเป็นระบบ บูรณาการกับการจัดการเรียนรู้ทุกกลุ่มสาระ และร่วมมือกับเครือข่าย เช่น มหาวิทยาลัยแม่โจ้ มหาวิทยาลัยเชียงใหม่ และสวนพฤกษศาสตร์สมเด็จพระนางเจ้าสิริกิติ์\\n\\nโครงการเป็นส่วนหนึ่งของโครงการอนุรักษ์พันธุกรรมพืชอันเนื่องมาจากพระราชดำริ (อพ.สธ.) โรงเรียนจัดแผนงาน ผู้รับผิดชอบ และงบประมาณผ่านกลุ่มบริหารวิชาการ ใช้พรรณไม้ในพื้นที่เป็นฐานการเรียนรู้ และได้รับคำปรึกษาจากเครือข่ายผู้เชี่ยวชาญ ผู้เรียนมีส่วนร่วมสำรวจ จำแนก บันทึก และสื่อสารข้อมูลพืช ผลการดำเนินงานนำไปสู่ผลงานของนักเรียนและการได้รับพระราชทานป้ายสนองพระราชดำริ\"}',NULL,'2026-10-06 08:40:55');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (351,155,2566,0,'{\"text\":\"โรงเรียนขับเคลื่อนการพัฒนาผู้เรียนผ่านกลุ่มแผนการเรียนด้านกีฬา ดนตรี อาชีพ และวิชาการ โดยวางแผนร่วมกัน พัฒนาสมรรถนะผ่านการฝึกปฏิบัติจริง ใช้เครือข่ายผู้เชี่ยวชาญและสถานประกอบการ สนับสนุนการแข่งขันและเวทีแสดงผลงาน และติดตามผลเพื่อนำมาปรับกิจกรรมให้ตอบสนองศักยภาพของผู้เรียน\\n\\nทั้ง 4 กลุ่มใช้ BANCHUEN Model เริ่มจากครูในกลุ่มสาระและผู้เกี่ยวข้องร่วมวิเคราะห์ความต้องการ วางหลักสูตรและกิจกรรม จัดเครือข่ายและพื้นที่ฝึกจริง แล้วติดตามผลจากผลงาน ทักษะ และเส้นทางศึกษาต่อ ตัวอย่างกิจกรรมมีการฝึกกีฬาและแข่งขัน การปฏิบัติดนตรี การฝึกทักษะอาชีพและ Summer Camp อุตสาหกรรม ตลอดจนหลักสูตรพิเศษและค่ายวิชาการ\"}',NULL,'2026-10-06 08:40:55');
