REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (805,140,2570,0,'{\"text\":\"โรงเรียนวิเคราะห์ความต้องการจำเป็นของผู้เรียน ชุมชน สังคม ท้องถิ่น และผู้มีส่วนเกี่ยวข้อง แล้วนำผลมาพัฒนาหลักสูตรให้ยืดหยุ่นและสอดคล้องกับหลักสูตรแกนกลาง ออกแบบการจัดการเรียนการสอนตามจุดมุ่งหมาย จัดทำแผนนิเทศ กำกับ ติดตาม และประเมินการใช้หลักสูตร ก่อนนำผลมาปรับปรุงหลักสูตรอย่างต่อเนื่อง\\n\\nคณะทำงานศึกษาหลักสูตรแกนกลาง มาตรฐานและตัวชี้วัด วิเคราะห์ข้อมูลผู้เรียนเป็นรายบุคคล รวมทั้งรับฟังความคิดเห็นจากผู้ปกครอง ชุมชน และหน่วยงานที่เกี่ยวข้อง ก่อนกำหนดโครงสร้างรายวิชาและแผนการเรียน โรงเรียนติดตามทั้งผลสัมฤทธิ์ สมรรถนะ คุณลักษณะ และความพร้อมศึกษาต่อ แล้วใช้ผลนิเทศและประเมินหลักสูตรปรับเนื้อหา เวลาเรียน และกิจกรรมให้เหมาะกับผู้เรียนแต่ละกลุ่ม\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (806,141,2570,0,'{\"text\":\"กิจกรรมเสริมหลักสูตรกำหนดจากข้อมูลนักเรียนรายบุคคลและความคิดเห็นของผู้ปกครอง ชุมชน และผู้เกี่ยวข้อง มีวัตถุประสงค์และกรอบดำเนินงานชัดเจน จัดกิจกรรมทั้งรายบุคคลและกลุ่มอย่างหลากหลาย ท้าทาย และสร้างสรรค์ ครอบคลุมผู้เรียนทุกกลุ่มเป้าหมาย และมุ่งให้เกิดผลงานหรือการพัฒนาต่อยอดที่เห็นได้ชัด\\n\\nตัวอย่างกิจกรรมมีทั้งห้องเรียนพิเศษนวัตกรรมวิทยาศาสตร์และเทคโนโลยี (IST), Summer Camp เทคโนโลยี กิจกรรมแผนการเรียนวิทยาศาสตร์สุขภาพ การทดลองในห้องปฏิบัติการของมหาวิทยาลัยแม่โจ้ ค่ายฝึกปฏิบัติการทางการแพทย์และอนุรักษ์สิ่งแวดล้อมทางทะเล รวมถึงการฝึกประสบการณ์ในโรงพยาบาลและสถานประกอบการ กิจกรรมเหล่านี้ช่วยให้ผู้เรียนเห็นเส้นทางศึกษาต่อและอาชีพผ่านการลงมือทำจริง\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (807,142,2570,0,'{\"text\":\"โรงเรียนรับฟังความต้องการของครู นักเรียน และผู้เกี่ยวข้องก่อนออกแบบและจัดหาสื่อ เทคโนโลยี และแหล่งเรียนรู้ที่สอดคล้องกับหลักสูตร มีระบบบริการและบำรุงรักษา ส่งเสริมการใช้แหล่งเรียนรู้ทั้งในโรงเรียน ท้องถิ่น และชุมชน รวมถึงเผยแพร่สื่อหรือนวัตกรรมที่ได้รับการยอมรับ\\n\\nครูเลือกใช้สื่อให้สัมพันธ์กับมาตรฐานการเรียนรู้และรูปแบบกิจกรรม เช่น การเรียนรู้จากการปฏิบัติ โครงงาน การอภิปราย และการเรียนรู้แบบร่วมมือ พร้อมใช้ห้องเรียน ห้องปฏิบัติการ ห้องสมุด แหล่งเรียนรู้ในชุมชน และหน่วยงานภายนอก โรงเรียนประเมินความพึงพอใจและประโยชน์ของสื่อ ดูแลความพร้อมของอุปกรณ์ และนำผลประเมินไปวางแผนจัดหาและพัฒนาในปีถัดไป\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (808,143,2570,0,'{\"text\":\"ครูวิเคราะห์ผู้เรียนเป็นรายบุคคล กำหนดเป้าหมายการเรียนรู้ ออกแบบกิจกรรมที่เน้นการลงมือปฏิบัติและการมีส่วนร่วม เลือกใช้สื่อ แหล่งเรียนรู้ และเทคโนโลยีให้เหมาะกับเนื้อหาและความแตกต่างของผู้เรียน พร้อมกำหนดวิธีวัดและประเมินผลให้สอดคล้องกับจุดประสงค์\\n\\nแผนการจัดการเรียนรู้ระบุมาตรฐาน ตัวชี้วัด สมรรถนะ คุณลักษณะ ภาระงาน และเกณฑ์ประเมินอย่างสอดคล้องกัน ผู้เรียนได้รับโอกาสตั้งคำถาม สืบค้น ทดลอง ทำโครงงาน อภิปราย และนำเสนอผลงาน ครูปรับระดับความยากและวิธีช่วยเหลือตามข้อมูลรายบุคคล เพื่อให้ทั้งกลุ่มที่ต้องพัฒนา กลุ่มทั่วไป และกลุ่มศักยภาพสูงก้าวหน้าได้\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (809,144,2570,0,'{\"text\":\"การจัดชั้นเรียนส่งเสริมการทำงานเป็นกลุ่ม การแลกเปลี่ยนความคิดเห็น การใช้เทคโนโลยี การเรียนรู้จากภูมิปัญญาท้องถิ่น และการช่วยเหลือผู้เรียนที่ต้องการการพัฒนาเพิ่มเติม ครูใช้ผลการสังเกต การสะท้อนคิด และข้อเสนอแนะของผู้เรียนเพื่อปรับกิจกรรมและบรรยากาศการเรียนรู้\\n\\nครูสร้างข้อตกลงและบรรยากาศที่ปลอดภัย เปิดโอกาสให้ผู้เรียนแสดงความคิดเห็นและประเมินการเรียนรู้ของตนเอง ใช้ชิ้นงาน แบบสังเกต แบบทดสอบ และการสนทนาสะท้อนผลเป็นข้อมูล เมื่อพบข้อบกพร่องจะจัดการสอนซ่อมเสริม ปรับกลุ่มเรียนหรือกิจกรรม ส่วนผู้เรียนที่มีศักยภาพจะได้รับโจทย์ท้าทายและโอกาสเข้าร่วมการแข่งขัน\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (810,135,2570,0,'{\"rows\":[{\"c1\":\"วิทยาศาสตร์และเทคโนโลยี\",\"c2\":18,\"c3\":120},{\"c1\":\"คณิตศาสตร์\",\"c2\":15,\"c3\":90},{\"c1\":\"ภาษาต่างประเทศ\",\"c2\":14,\"c3\":85},{\"c1\":\"ภาษาไทย\",\"c2\":12,\"c3\":60},{\"c1\":\"สังคมศึกษา ศาสนาและวัฒนธรรม\",\"c2\":14,\"c3\":70},{\"c1\":\"สุขศึกษาและพลศึกษา\",\"c2\":8,\"c3\":40},{\"c1\":\"ศิลปะ ดนตรีและนาฏศิลป์\",\"c2\":8,\"c3\":45},{\"c1\":\"การงานอาชีพ\",\"c2\":8,\"c3\":50},{\"c1\":\"ส่งเสริมการศึกษา\\/แนะแนว\",\"c2\":5,\"c3\":30}],\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (811,147,2570,0,'{\"text\":\"โรงเรียนใช้ผลการทดสอบระดับชาติ ผลสัมฤทธิ์ตามหลักสูตร ผลการอ่าน คิดวิเคราะห์และเขียน ตลอดจนข้อมูลรายบุคคลของผู้เรียนมาวิเคราะห์จุดแข็งและประเด็นพัฒนา จัดกิจกรรมยกระดับผลสัมฤทธิ์ การสอนซ่อมเสริม การแนะแนว และกิจกรรมส่งเสริมความเป็นเลิศตามศักยภาพ\\n\\nสำหรับ O-NET โรงเรียนนำผลระดับ ม.3 และ ม.6 มาวิเคราะห์รายวิชา รายมาตรฐาน ตัวชี้วัด และรายบุคคล แล้วแบ่งผู้เรียนเป็นกลุ่มที่ต้องพัฒนาเร่งด่วน กลุ่มที่ควรส่งเสริมเพิ่มเติม และกลุ่มศักยภาพสูง มีโครงการพัฒนาผลสัมฤทธิ์ กิจกรรมเตรียมความพร้อมสู่มหาวิทยาลัย การนิเทศการสอน และการทดสอบ Pre-test\\/Post-test รวมถึงแนวทาง SANSAI O-NET SMART ที่ใช้ข้อมูลร่วมกับการเรียนรู้เชิงรุกเพื่อแก้จุดอ่อนอย่างตรงจุด\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (812,148,2570,0,'{\"text\":\"โรงเรียนส่งเสริมการอ่านและเขียนภาษาไทย การใช้ภาษาอังกฤษเพื่อการสื่อสาร การคิดคำนวณ การคิดวิเคราะห์ การแก้ปัญหา และการศึกษาค้นคว้าด้วยตนเอง ผ่านกิจกรรมการเรียนรู้เชิงรุก โครงงาน การแข่งขัน และการสร้างนวัตกรรม โดยสนับสนุนให้ผู้เรียนอธิบายกระบวนการทำงาน นำผลงานไปใช้ และเผยแพร่ได้\\n\\nโรงเรียนติดตามผลการอ่าน-เขียนภาษาไทย ทักษะภาษาอังกฤษ รายวิชาการศึกษาค้นคว้าด้วยตนเอง (IS) การอ่านคิดวิเคราะห์และเขียน และความสามารถด้านเทคโนโลยีอย่างต่อเนื่อง ผู้เรียนได้สร้างชิ้นงานและโครงงาน อธิบายขั้นตอน ทดลองแก้ปัญหา และนำเสนอในเวทีทั้งภายในและภายนอก ผลงานการแข่งขันระดับจังหวัด ภูมิภาค ชาติ และนานาชาติถูกใช้เป็นหลักฐานประกอบการประเมินและเป็นแรงจูงใจในการพัฒนาต่อ\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (813,149,2570,0,'{\"text\":\"โรงเรียนสร้างและพัฒนาแนวทาง ระเบียบ และเครื่องมือวัดประเมินผลที่หลากหลายและสอดคล้องกับสิ่งที่ต้องการวัด มีส่วนร่วมจากครู นักเรียน ผู้ปกครอง และผู้เกี่ยวข้อง จัดเก็บข้อมูลอย่างเป็นระบบ และจัดทำเอกสารประกอบการวัดประเมินผลเพื่อใช้ติดตามพัฒนาการของผู้เรียน\\n\\nเครื่องมือครอบคลุมแบบทดสอบ ภาระงาน ชิ้นงาน โครงงาน แบบสังเกต และเกณฑ์รูบริก โดยกำหนดให้สัมพันธ์กับมาตรฐาน ตัวชี้วัด และสมรรถนะที่ต้องการ โรงเรียนตรวจสอบคุณภาพเครื่องมือ จัดเก็บคะแนนและหลักฐานอย่างเป็นระบบ และสื่อสารเกณฑ์ให้ผู้เรียนทราบ รวมทั้งเปิดโอกาสให้ผู้เรียนประเมินตนเองและใช้ข้อมูลจากผู้ปกครองประกอบเมื่อเหมาะสม\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (814,150,2570,0,'{\"text\":\"ครูและผู้บริหารนำผลการประเมินก่อนเรียน ระหว่างเรียน และหลังเรียนมาวิเคราะห์แนวโน้ม ให้ข้อมูลย้อนกลับแก่ผู้เรียน วางแผนซ่อมเสริมหรือส่งเสริมความสามารถเฉพาะด้าน ปรับแผนการสอน และรายงานผลต่อผู้ปกครอง เพื่อให้การพัฒนาผู้เรียนต่อเนื่องและตอบสนองความแตกต่างรายบุคคล\\n\\nผลประเมินถูกนำไปจัดกลุ่มและวางแผนช่วยเหลือรายบุคคล ไม่ใช้เพียงตัดสินผลการเรียน ครูวิเคราะห์ข้อผิดพลาดและให้ข้อมูลย้อนกลับที่ระบุสิ่งที่ทำได้ สิ่งที่ต้องปรับ และแนวทางฝึกเพิ่มเติม จากนั้นติดตามผลหลังการซ่อมเสริมหรือส่งเสริม พร้อมใช้ข้อมูลระดับห้องเรียนและระดับโรงเรียนกำหนดโครงการและเป้าหมายในปีถัดไป\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (815,155,2570,0,'{\"text\":\"โรงเรียนขับเคลื่อนการพัฒนาผู้เรียนผ่านกลุ่มแผนการเรียนด้านกีฬา ดนตรี อาชีพ และวิชาการ โดยวางแผนร่วมกัน พัฒนาสมรรถนะผ่านการฝึกปฏิบัติจริง ใช้เครือข่ายผู้เชี่ยวชาญและสถานประกอบการ สนับสนุนการแข่งขันและเวทีแสดงผลงาน และติดตามผลเพื่อนำมาปรับกิจกรรมให้ตอบสนองศักยภาพของผู้เรียน\\n\\nทั้ง 4 กลุ่มใช้ BANCHUEN Model เริ่มจากครูในกลุ่มสาระและผู้เกี่ยวข้องร่วมวิเคราะห์ความต้องการ วางหลักสูตรและกิจกรรม จัดเครือข่ายและพื้นที่ฝึกจริง แล้วติดตามผลจากผลงาน ทักษะ และเส้นทางศึกษาต่อ ตัวอย่างกิจกรรมมีการฝึกกีฬาและแข่งขัน การปฏิบัติดนตรี การฝึกทักษะอาชีพและ Summer Camp อุตสาหกรรม ตลอดจนหลักสูตรพิเศษและค่ายวิชาการ\",\"copiedFrom\":\"ปีการศึกษา 2568\"}',1,'2026-10-19 15:10:53');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (816,146,2569,0,'{\"text\":\"โรงเรียนบริหารงบประมาณ การเงิน พัสดุ และสินทรัพย์ให้สอดคล้องกับแผนพัฒนาคุณภาพและแผนปฏิบัติการประจำปี โดยยึดความถูกต้อง โปร่งใส ตรวจสอบได้ และความคุ้มค่า สนับสนุนทรัพยากรต่อภารกิจหลักทั้งด้านผู้เรียน บุคลากร หลักสูตร เทคโนโลยี และสภาพแวดล้อม\\n\\nขั้นวางแผนนำกลยุทธ์และมาตรฐานของโรงเรียนมาจัดทำแผนปฏิบัติการ โดยแต่ละโครงการระบุวัตถุประสงค์ ตัวชี้วัด ผู้รับผิดชอบ และงบประมาณชัดเจน ระหว่างดำเนินงานมีการควบคุมเอกสาร การจัดซื้อจัดจ้าง และการใช้ทรัพย์สินตามระเบียบ เมื่อสิ้นโครงการจะประเมินผลและความคุ้มค่า เพื่อนำข้อมูลไปจัดลำดับความสำคัญของงบประมาณรอบใหม่\"}',1,'2026-10-21 08:40:56');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (821,159,2569,0,'{\"text\": \"ปรัชญา: วิชาเป็นเลิศ เทิดคุณธรรม นำสามัคคี\\n\\nวัฒนธรรมองค์กร: ผู้บริหาร ครู บุคลากร และนักเรียน รักสามัคคี ศรัทธาและภูมิใจในสถาบัน ตามวิถีสันทราย\\n\\nวิถีสันทรายและอัตลักษณ์ของลูกสันทราย: ยิ้ม ไหว้ ทักทาย สุภาพอ่อนน้อม แต่งกายดี มีจิตสาธารณะ\\n\\nค่านิยม: องค์กรแห่งอนาคต\\n\\nเอกลักษณ์: สภาพแวดล้อมเอื้อต่อการจัดการเรียนรู้ มีมหาวิทยาลัยแม่โจ้เป็นแหล่งเรียนรู้ และได้รับความร่วมมือจากชุมชน ผู้ปกครองและหน่วยงานในท้องถิ่น\\n\\nจุดเด่น: ใช้ข้อมูลจริงและการมีส่วนร่วมเป็นฐานในการกำหนดมาตรฐานและพัฒนาคุณภาพสถานศึกษา\"}',NULL,'2026-10-30 09:51:37');
