REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (830,168,2569,0,'{\"text\": \"โรงเรียนมีพื้นที่รวม 35 ไร่ 2 งาน 5 ตารางวา ส่วนลักษณะที่ดินและประเภทกรรมสิทธิ์การถือครองที่ดินยังไม่พบข้อมูลยืนยันในเล่ม 5 ด้าน\"}',NULL,'2026-10-30 09:51:38');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (832,169,2569,0,'{\"text\": \"โรงเรียนสันทรายวิทยาคมเป็นสถานศึกษาที่สร้างสรรค์คนดี มีทักษะแห่งอนาคต มุ่งสู่ความเป็นเลิศตามศักยภาพ ภายในปี 2570\"}',NULL,'2026-10-30 09:51:38');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (833,170,2569,0,'{\"text\": \"1. ส่งเสริมการจัดการศึกษาเพื่อสร้างทักษะแห่งอนาคต ให้ผู้เรียนมีความเป็นเลิศตามศักยภาพ\\n2. ส่งเสริมคุณลักษณะที่พึงประสงค์และค่านิยมที่ดีบนพื้นฐานความเป็นไทย พร้อมสร้างภูมิคุ้มกันจากภัยทุกรูปแบบ\\n3. เพิ่มโอกาสให้ผู้เรียนทุกคนได้รับบริการทางการศึกษาอย่างเท่าเทียมบนพื้นฐานการมีส่วนร่วม\\n4. พัฒนาครูและบุคลากรให้เชี่ยวชาญตามมาตรฐานวิชาชีพและตอบสนองทิศทางการพัฒนาผู้เรียน\\n5. พัฒนาสถานศึกษาและระบบบริหารจัดการให้เอื้อต่อการพัฒนาคุณภาพและสอดคล้องกับบริบท\"}',NULL,'2026-10-30 09:51:38');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (834,171,2569,0,'{\"text\": \"1. ผู้เรียนมีทักษะแห่งอนาคตและได้รับการส่งเสริมสู่ความเป็นเลิศตามศักยภาพ\\n2. ผู้เรียนมีคุณลักษณะอันพึงประสงค์และค่านิยมที่ดีบนพื้นฐานความเป็นไทย พร้อมมีภูมิคุ้มกันจากภัยทุกรูปแบบ\\n3. ผู้เรียนทุกคนได้รับบริการทางการศึกษาอย่างเท่าเทียมบนพื้นฐานการมีส่วนร่วม\\n4. ครูและบุคลากรได้รับการพัฒนาและมีความเชี่ยวชาญตามมาตรฐานวิชาชีพ\\n5. สถานศึกษามีระบบบริหารจัดการที่เอื้อต่อการพัฒนาคุณภาพและสอดคล้องกับบริบท\"}',NULL,'2026-10-30 09:51:38');
REPLACE INTO `records` (`id`, `topic_id`, `academic_year`, `term`, `data_json`, `updated_by`, `updated_at`) VALUES (835,172,2569,0,'{\"text\": \"กลยุทธ์ที่ 1 พัฒนาผู้เรียนให้มีทักษะแห่งอนาคตและเป็นเลิศตามศักยภาพ โดยพัฒนาหลักสูตร ทักษะ ผลสัมฤทธิ์ คุณลักษณะและโอกาสทางการศึกษา\\n\\nกลยุทธ์ที่ 2 พัฒนาครูและบุคลากรทางการศึกษาให้สามารถจัดการศึกษาที่สนับสนุนการสร้างทักษะแห่งอนาคต และจัดการเรียนรู้เชิงรุก\\n\\nกลยุทธ์ที่ 3 พัฒนาระบบบริหารจัดการให้มีประสิทธิภาพและประสิทธิผลบนพื้นฐานการมีส่วนร่วม ครอบคลุมงานวิชาการ งานบุคคล สภาพแวดล้อม การเงิน สินทรัพย์และการประกันคุณภาพ\"}',NULL,'2026-10-30 09:51:38');
